var e={id:`k1-04-hucre-hasari-ve-nekroz-i`,sira:4,kurul:1,ders:`Tıbbi Patoloji`,konu:`Hücre Hasarı ve Nekroz - I`,ogretim_uyesi:`Prof. Dr. Hikmet Keleş`,tarih:`2026-09-15`,soru_sayisi:132,kazanimlar:[{no:1,metin:`Hücre hasarı kavramını ve hücrenin strese yanıtlarını tanımlar.`,sorular:[{id:`k1-04-q01`,kazanim:1,zorluk:`kolay`,soru:`Hücrenin normal homeostazını koruyamadığı ve sonucu geri dönüşümlü bozukluk ya da hücre ölümü olabilen duruma ne ad verilir?`,secenekler:{A:`Hücre hasarı`,B:`Hücresel adaptasyon`,C:`Hiperplazi`,D:`Metaplazi`,E:`Senesens`},dogru:`A`,aciklama:`Hücre hasarı homeostazın korunamamasıdır; sonuç geri dönüşümlü hasar veya geri dönüşümsüz hasar ve hücre ölümüdür.`,sik_aciklamalari:{A:`Doğru. Hücre hasarı birçok hastalığın temelini oluşturur.`,B:`Adaptasyonda hücre yeni bir denge kurar; homeostaz kaybı değil, uyumdur.`,C:`Hiperplazi bir adaptasyon tipidir (hücre sayısı artışı).`,D:`Metaplazi olgun hücre tipi değişimidir; bir adaptasyondur.`,E:`Senesens hücresel yaşlanmadır.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-04-q02`,kazanim:1,zorluk:`orta`,soru:`Zararlı bir uyarana maruz kalan sağlıklı hücrede olayların tipik sırası aşağıdakilerden hangisidir?`,secenekler:{A:`Hücre ölümü → geri dönüşümlü hasar → geri dönüşümsüz hasar`,B:`Geri dönüşümsüz hasar → geri dönüşümlü hasar → hücre ölümü`,C:`Geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü (nekroz/apoptoz)`,D:`Apoptoz → nekroz → geri dönüşümlü hasar`,E:`Adaptasyon → hücre ölümü → geri dönüşümlü hasar`},dogru:`C`,aciklama:`Sağlıklı hücre → zararlı uyaran → geri dönüşümlü hasar → (şiddetli/ilerleyici) geri dönüşümsüz hasar → hücre ölümü.`,sik_aciklamalari:{A:`Hücre ölümü sürecin son basamağıdır, başlangıcı değildir.`,B:`Geri dönüşümsüz hasar geri dönüşümlü hasardan sonra gelir.`,C:`Doğru. Hasar ilerledikçe geri dönüşümsüz hale gelir ve ölümle sonuçlanır.`,D:`Apoptoz ve nekroz sürecin sonundadır.`,E:`Adaptasyon başarısız olursa hasar, sonra ölüm gelişir; sıra yanlıştır.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-04-q03`,kazanim:1,zorluk:`zor`,soru:`Hücre hasarında morfolojik değişikliklerin zamanlaması ile ilgili aşağıdaki ifadelerden hangisi doğrudur?`,secenekler:{A:`Işık mikroskobik değişiklikler hücre ölümünden önce ortaya çıkar.`,B:`Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir.`,C:`Makroskobik değişiklikler elektron mikroskobik değişikliklerden önce görülür.`,D:`Hücre işlevini kaybettiği anda her zaman ölmüştür.`,E:`Morfolojik değişiklik görülmeyen dokuda hasar olamaz.`},dogru:`B`,aciklama:`Hücreler hızla işlevsiz hale gelip yine canlı kalabilir; ölüm, mikroskopta ve çıplak gözle görülen değişikliklerden önce gerçekleşir.`,sik_aciklamalari:{A:`Işık mikroskobik değişiklikler hücre ölümünden sonra görünür hale gelir.`,B:`Doğru. Biyokimyasal ölüm morfolojik bulgulardan önce gelir.`,C:`Sıra ultrastrüktürel → ışık mikroskobik → makroskobik şeklindedir.`,D:`İşlev kaybı olan hücre bir süre canlı kalabilir.`,E:`Erken dönemde morfolojik bulgu olmadan hasar ve ölüm olabilir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q04`,kazanim:1,zorluk:`orta`,soru:`Hipoksiye maruz kalan bir dokuda hücrelerin önce şişme ve yağlanma gibi geri dönüşlü değişiklikler gösterdiği, uyaran kaldırılınca normale döndükleri, uyaran sürünce ise kalıcı hasar ve ölümün geliştiği bir şemayla anlatılmaktadır. Hücre hasarı ve stres yanıtlarıyla ilgili sıralamalardan hangisi doğrudur?`,secenekler:{A:`Hücre hasarı hücrenin homeostazını güçlendirdiği durumdur`,B:`Hasarlı hücre her zaman doğrudan nekroza gider, ara basamak yoktur`,C:`Sağlıklı hücre → geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü`,D:`Adaptasyon hücre ölümünün bir tipidir`,E:`Geri dönüşümlü hasarda membran bütünlüğü her zaman bozulur`},dogru:`C`,aciklama:`Hücre hasarı hücrenin homeostazını koruyamadığı durumdur ve sonucu geri dönüşümlü bozukluk ya da geri dönüşümsüz hasar-ölümdür. Sağlıklı hücre zararlı uyarana önce geri dönüşümlü hasarla, uyaran sürerse geri dönüşümsüz hasar ve ölümle yanıt verir.`,sik_aciklamalari:{A:`Hasar homeostazın korunamadığı durumdur.`,B:`Yanıt dereceli bir sıra izler; önce geri dönüşümlü basamak gelir.`,C:`Doğru. Hücresel yanıt bu sırayla ilerler; adaptasyon yeni denge kurar, uyaran sürerse hasar ve ölüm gelişir.`,D:`Adaptasyon yeni denge kurma yanıtıdır, ölüm biçimi değildir.`,E:`Geri dönüşümlü hasarda membran bütünlüğü korunur.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q05`,kazanim:1,zorluk:`zor`,soru:`Akut iskemi gelişen bir miyokard bölgesinde, henüz ışık mikroskobunda belirgin değişiklik izlenmezken kontraktil fonksiyonun kaybolduğu ve biyokimyasal belirteçlerin yükseldiği gözlenmiştir. Bu gözlemle ilgili ifadelerden hangisi doğrudur?`,secenekler:{A:`Makroskobik değişiklikler her zaman hücre ölümünden önce gelir`,B:`Hücre ölümü morfolojik değişikliklerden önce gerçekleşebilir; işlev kaybı erken bulgudur`,C:`Hücreler işlevlerini yitirmeden morfolojik olarak ölür`,D:`Işık mikroskobik bulgu olmadan hasardan söz edilemez`,E:`Ultrastrüktürel değişiklikler ölümden sonra ortaya çıkar`},dogru:`B`,aciklama:`Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir; hücreler hızla işlevsiz hale gelip yine de canlı kalabilir. Fonksiyon kaybı morfolojik bulgudan önce ortaya çıkar.`,sik_aciklamalari:{A:`Ölüm morfolojik değişikliklerden önce gelebilir.`,B:`Doğru. Hücreler hızla işlevsiz hale gelip yine de canlı kalabilir; ölüm ultrastrüktürel değişikliklerden önce gelir.`,C:`İşlev kaybı morfolojiden önce ortaya çıkar.`,D:`Fonksiyonel bozukluk morfolojiden önce başlayabilir.`,E:`Ultrastrüktürel değişiklikler en erken morfolojik basamaktır.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q06`,kazanim:1,zorluk:`orta`,soru:`Hücre hasarının tanımını doğru veren seçenek hangisidir?`,secenekler:{A:`Homeostazın korunmasıdır`,B:`Homeostazın korunamamasıdır`,C:`Hücrenin bölünmesidir`,D:`Hücrenin büyümesidir`,E:`Doku onarımıdır`},dogru:`B`,aciklama:`Hücre hasarı, hücrenin değişen koşullara rağmen homeostazını koruyamadığı durumdur. Hafif uyaranlarda adaptasyonla yeni denge kurulur, uyaran sürerse önce geri dönüşümlü hasar gelişir. Şiddetli ve ilerleyici streste geri dönüşümsüz hasar ve nekroz veya apoptozla hücre ölümü ortaya çıkar.`,sik_aciklamalari:{A:`Homeostazın korunması sağlıklı durumu tanımlar, hasar değildir.`,B:`Doğru. İç dengenin sürdürülememesi hasarın tanımıdır.`,C:`Bölünme proliferasyondur, hasar kavramı değildir.`,D:`Büyüme hipertrofidir, hasar değildir.`,E:`Onarım hasar sonrası iyileşmedir, hasarın kendisi değildir.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q07`,kazanim:1,zorluk:`orta`,soru:`Zararlı uyarana hücresel yanıtın doğru sıralaması nedir?`,secenekler:{A:`Ölüm, hasar, adaptasyon`,B:`Hasar, ölüm, sağlık`,C:`Adaptasyon, ölüm, sağlık`,D:`Adaptasyon, geri dönüşümlü, geri dönüşümsüz`,E:`Nekroz, sağlık, adaptasyon`},dogru:`D`,aciklama:`Zararlı uyaran önce geri dönüşümlü hasara yol açar; uyaran kaldırılırsa hücre normale döner. Uyaran şiddetli ve ilerleyici olursa geri dönüşümsüz hasar eşiği aşılır. Sonuç, zar bütünlüğünün yitirildiği nekroz veya programlı apoptozdur.`,sik_aciklamalari:{A:`Ölüm ilk basamak olamaz, spektrumun sonudur.`,B:`Sağlık başlangıç noktasıdır, hasardan sonra gelmez.`,C:`Sağlık sonuç değil başlangıçtır.`,D:`Doğru. Uyaran şiddetlenince yanıt basamakları sırayla ilerler.`,E:`Nekroz sonuçtur, başlangıç değildir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q08`,kazanim:1,zorluk:`orta`,soru:`Patolojide 'hücre hasarı (zedelenmesi)' kavramının temel tanımı aşağıdakilerden hangisinde en doğru verilmiştir?`,secenekler:{A:`Hücrenin genetik olarak mutasyona uğramasıdır.`,B:`Fizyolojik streslerin veya zedeleyici zararlı uyaranların hücrenin iç ve dış adaptasyon kapasitesini aşması sonucu normal homeostatik dengenin korunamaması ve biyokimyasal/yapısal bozulmanın başlamasıdır.`,C:`Hücre zarının sadece glikoz moleküllerine karşı geçirgenliğini kaybetmesidir.`,D:`Hücrenin kontrolsüz çoğalarak karsinom oluşturmasıdır.`,E:`Sadece bakteriyel toksinlerle oluşan mekanik doku yırtılmasıdır.`},dogru:`B`,aciklama:`Hücre hasarı, zedeleyici uyaranların hücrenin adaptasyon sınırlarını aşması sonucu hücresel homeostazın bozulması, hücresel bileşenlerin işlevsizleşmesi durumudur.`,sik_aciklamalari:{A:`Mutasyon spesifik bir genetik olaydır, tüm hasarları tanımlamaz.`,B:`Doğru. Adaptif sınırların aşılması ve homeostazın çökmesi hücre hasarının tam tanımıdır.`,"C, D, E":`Dar veya farklı patolojik süreçleri ifade eden seçeneklerdir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q09`,kazanim:1,zorluk:`zor`,soru:`Hücre zedelenmesinde 'zamansal gelişim sırası' (kronolojik sıra) ilkeleri incelendiğinde Robbins patolojisine göre aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Önce çıplak gözle makroskopik nekroz görülür, saatler sonra ATP azalır ve en son hücre ölür.`,B:`Zedeleyici etkenle karşılaşan hücrede ilk dakikalarda biyokimyasal ve moleküler fonksiyon kaybı başlar; bunu hücre ölümü takip eder; ultrastrüktürel (elektron mikroskobu), ışık mikroskobik ve kaba makroskopik morfolojik değişiklikler ise hücre ölümünden saatler veya günler sonra belirir.`,C:`Işık mikroskobundaki morfolojik değişiklikler biyokimyasal bozulmadan her zaman önce gelir.`,D:`Elektron mikroskobu makroskobik lezyondan daha geç bulgu verir.`,E:`Tüm süreçler aynı milisaniyede eşzamanlı olarak belirir.`},dogru:`B`,aciklama:`Zaman çizelgesi: 1. Biyokimyasal/moleküler fonksiyon kaybı (dakikalar), 2. Hücre ölümü (20-60 dk), 3. Elektron mikroskobik değişimler (saatler), 4. Işık mikroskobu bulguları (4-12 saat), 5. Makroskopik morfoloji (12-24 saat). Fonksiyon kaybı ve ölüm morfolojiden önce gelir.`,sik_aciklamalari:{"A, C, D, E":`Hücre hasarının zamansal hiyerarşisine tamamen aykırıdır.`,B:`Doğru. Biyokimyasal kayıp → Hücre ölümü → Elektron mikroskobu → Işık mikroskobu → Makroskopik morfoloji kesin kronolojik akıştır.`},bilgi:[2,10],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q10`,kazanim:1,zorluk:`orta`,soru:`Hücresel hasarda 'homeostaz' kavramının karşılığı aşağıdakilerden hangisidir?`,secenekler:{A:`Hücrenin sürekli mitoz bölünme halinde olması`,B:`Hücrenin fizyolojik sınırları içerisinde kalarak iç ortamının (iyon, su, pH, ATP) dengesini sabit tutabilme yeteneği`,C:`Hücrenin sadece lipid depolaması`,D:`Hücrenin oksijensiz ortamda sonsuz yaşayabilmesi`,E:`Plazma zarının tamamen geçirgen hale gelmesi`},dogru:`B`,aciklama:`Homeostaz, dış ortamdaki dalgalanmalara rağmen hücrenin iç dengesini (fizyolojik sabitliği) korumasıdır.`,sik_aciklamalari:{"A, C, D, E":`Homeostaz kavramıyla uyuşmayan durumlardır.`,B:`Doğru. İç ortam dengesinin korunabilmesi homeostazın tanımıdır.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q11`,kazanim:1,zorluk:`zor`,soru:`Bir dokuda meydana gelen zedelenmenin geri dönüşümlü (reversible) evreden geri dönüşümsüz (irreversible) evreye ve hücre ölümüne geçişinde rol oynayan kritik hücresel hedefler arasında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`Mitokondriyal oksidatif fosforilasyon ve ATP üretim kapasitesi`,B:`Plazma zarı ve intraselüler organel zarlarının yapısal bütünlüğü`,C:`Hücre içi kalsiyum homeostazı ve enzim aktivasyonu`,D:`DNA ve nükleer kromatin bütünlüğü`,E:`Hücrenin hücre dışı matriksteki elastik liflerin rengini belirleme yeteneği`},dogru:`E`,aciklama:`Hücre hasarının temel biyolojik hedefleri: Mitokondri, hücre zarları, kalsiyum dengesi, serbest radikaller ve genetik materyaldir (DNA/protein). Ekstraselüler lif rengi gibi yapay bir parametre hücresel hasar hedefi değildir.`,sik_aciklamalari:{"A, B, C, D":`Hücre hasarının klasik beş temel hücresel ve moleküler hedefidir.`,E:`Doğru (yer almaz). Hasar mekanizmasıyla ilgisizdir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q12`,kazanim:1,zorluk:`orta`,soru:`Hücre hasarı gelişen bir dokuda zedeleyici etken ortadan kalktığında hücrenin tamamen normale dönebilmesi hangi durumu ifade eder?`,secenekler:{A:`Geri dönüşümlü (reversible) hücre hasarı`,B:`Koagülasyon nekrozu`,C:`Likidasyon nekrozu`,D:`Apoptoz`,E:`Senil kalsifikasyon`},dogru:`A`,aciklama:`Zararlı etken kalktığında morfolojik ve fonksiyonel bozuklukların tamamen düzelebildiği erken evre geri dönüşümlü (reversible) hücre zedelenmesidir.`,sik_aciklamalari:{A:`Doğru. Normale dönebilen erken hasar tipi geri dönüşümlü hasardır.`,"B, C, D, E":`Hücrenin öldüğü geri dönüşümsüz süreçlerdir.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q13`,kazanim:1,zorluk:`kolay`,soru:`"Koagülatif nekroz" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{C:`En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,B:`Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir.`,D:`Sağlıklı hücre → zararlı uyaran → geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü (nekroz/apoptoz).`,A:`Hücrenin normal homeostazını koruyamadığı durumdur.`,E:`Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`},dogru:`C`,aciklama:`Doğru: En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,sik_aciklamalari:{C:`Doğru. En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,B:`Yanlış. Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir.`,D:`Yanlış. Sağlıklı hücre → zararlı uyaran → geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü (nekroz/apoptoz).`,A:`Yanlış. Hücrenin normal homeostazını koruyamadığı durumdur.`,E:`Yanlış. Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q14`,kazanim:1,zorluk:`orta`,soru:`"Hücresel hasarda ana hedefler" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`,A:`Doku tamamen erir ve viskoz sıvıya döner.`,C:`Hipoksi oksijen eksikliği, iskemi kan akımının azalması veya kesilmesidir.`,D:`Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`,B:`Birçok hücre etkilendiğinde organ soluk görünür, turgoru artar, ağırlığı artabilir.`},dogru:`E`,aciklama:`Doğru: Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`,sik_aciklamalari:{E:`Doğru. Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`,A:`Yanlış. Doku tamamen erir ve viskoz sıvıya döner.`,C:`Yanlış. Hipoksi oksijen eksikliği, iskemi kan akımının azalması veya kesilmesidir.`,D:`Yanlış. Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`,B:`Yanlış. Birçok hücre etkilendiğinde organ soluk görünür, turgoru artar, ağırlığı artabilir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q15`,kazanim:1,zorluk:`orta`,soru:`"Koagülatif nekroz mikroskopisi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{D:`Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,E:`Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,B:`Koagülatif, sıvılaşma (likefaksiyon), gangrenöz, kazeöz, yağ ve fibrinoid nekroz.`,C:`Sağlıklı hücre → zararlı uyaran → geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü (nekroz/apoptoz).`,A:`Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`},dogru:`D`,aciklama:`Doğru: Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,sik_aciklamalari:{D:`Doğru. Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,E:`Yanlış. Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,B:`Yanlış. Koagülatif, sıvılaşma (likefaksiyon), gangrenöz, kazeöz, yağ ve fibrinoid nekroz.`,C:`Yanlış. Sağlıklı hücre → zararlı uyaran → geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü (nekroz/apoptoz).`,A:`Yanlış. Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`},bilgi:[29],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k01-q16`,kazanim:1,zorluk:`zor`,soru:`"Toksinler" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{E:`Çevresel (hava kirleticileri, böcek ilaçları, karbon monoksit, asbest), yaşam tarzı (sigara, etanol) ve ilaç kaynaklı.`,A:`Bakteri, virüs, mantar ve parazitlerin tümü hasar verebilir.`,D:`Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`,C:`Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,B:`Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`},dogru:`E`,aciklama:`Doğru: Çevresel (hava kirleticileri, böcek ilaçları, karbon monoksit, asbest), yaşam tarzı (sigara, etanol) ve ilaç kaynaklı.`,sik_aciklamalari:{E:`Doğru. Çevresel (hava kirleticileri, böcek ilaçları, karbon monoksit, asbest), yaşam tarzı (sigara, etanol) ve ilaç kaynaklı.`,A:`Yanlış. Bakteri, virüs, mantar ve parazitlerin tümü hasar verebilir.`,D:`Yanlış. Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`,C:`Yanlış. Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,B:`Yanlış. Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`},bilgi:[5],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:2,metin:`Hücre hasarının başlıca nedenlerini sıralar.`,sorular:[{id:`k1-04-q04`,kazanim:2,zorluk:`kolay`,soru:`Hücre hasarı ve nekrozun en sık nedenlerinden biri olan, kan akımının azalması veya kesilmesi durumuna ne ad verilir?`,secenekler:{A:`Hipoksi`,B:`Hiperemi`,C:`Konjesyon`,D:`İskemi`,E:`Ödem`},dogru:`D`,aciklama:`İskemi kan akımının azalması/kesilmesidir; oksijen ve besin azalır, atıklar uzaklaştırılamaz. Hipoksi yalnızca oksijen eksikliğini ifade eder.`,sik_aciklamalari:{A:`Hipoksi oksijen eksikliğidir; kan akımı korunmuş olabilir (ör. anemi).`,B:`Hiperemi aktif kan akımı artışıdır.`,C:`Konjesyon venöz drenajın bozulmasıyla pasif kan birikimidir.`,D:`Doğru. İskemide hem oksijen hem besin eksikliği vardır.`,E:`Ödem interstisyel sıvı artışıdır.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-04-q05`,kazanim:2,zorluk:`orta`,soru:`Kapalı bir garajda motor çalışırken bilinci bulanıklaşan bir hastada hücre hasarının temel mekanizması aşağıdakilerden hangisidir?`,secenekler:{A:`Hemoglobine bağlanarak oksijen taşınmasını bozan karbon monoksite bağlı hipoksi`,B:`Mikrobiyal toksin üretimi`,C:`Otoimmün antikor aracılı hasar`,D:`Nokta mutasyonuna bağlı protein kaybı`,E:`Ani basınç değişikliğine bağlı gaz embolisi`},dogru:`A`,aciklama:`Karbon monoksit hemoglobine bağlanarak oksijen taşınmasını bozar ve hipoksik hücre hasarı yapar; aynı zamanda çevresel bir toksindir.`,sik_aciklamalari:{A:`Doğru. CO zehirlenmesi hipoksi nedenleri arasındadır.`,B:`Enfeksiyöz ajanların mekanizmasıdır.`,C:`İmmünolojik hasar mekanizmasıdır.`,D:`Genetik anormalliklerin mekanizmasıdır.`,E:`Dekompresyon hastalığı gibi fiziksel etken mekanizmasıdır.`},bilgi:[4,5],benzer_cikmis:[]},{id:`k1-04-q06`,kazanim:2,zorluk:`orta`,soru:`Hücre hasarı nedenleri ile örnekleri arasındaki eşleştirmelerden hangisi yanlıştır?`,secenekler:{A:`Genetik anormallik – orak hücreli anemi`,B:`Fiziksel etken – dalgıçlarda dekompresyon hastalığı`,C:`Beslenme dengesizliği – obezite ve tip 2 diyabet`,D:`Toksin – etanol ve sigara dumanı`,E:`İmmünolojik reaksiyon – protein-kalori malnütrisyonu`},dogru:`E`,aciklama:`Protein-kalori malnütrisyonu beslenme dengesizliğinin (yetersiz alım) örneğidir; immünolojik nedenler otoimmünite, alerji ve aşırı immün yanıttır.`,sik_aciklamalari:{A:`Doğru eşleştirme; nokta mutasyonu örneğidir.`,B:`Doğru eşleştirme; ani basınç değişikliği fiziksel etkendir.`,C:`Doğru eşleştirme; aşırı alım da beslenme dengesizliğidir.`,D:`Doğru eşleştirme; yaşam tarzı kaynaklı toksinlerdir.`,E:`Yanlış eşleştirme (aranan cevap). Protein-kalori malnütrisyonu beslenme dengesizliğinin (yetersiz alım) örneğidir; immünolojik nedenler otoimmünite, alerji ve aşırı immün yanıttır.`},bilgi:[5,7,8,9,10],benzer_cikmis:[]},{id:`k1-04-q07`,kazanim:2,zorluk:`zor`,soru:`Hücre hasarında hücresel hedefler ve etken özellikleri ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?`,secenekler:{A:`Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA ve sitoiskelet başlıca hedeflerdir.`,B:`Birden fazla hücresel hedef aynı anda etkilenebilir.`,C:`İlaçlar terapötik dozda güvenli olup yüksek dozda veya duyarlı bireyde toksik olabilir.`,D:`Enfeksiyöz ajanlar hasarı yalnızca doğrudan toksin üretimiyle yapar; bağışıklık yanıtı hasara katkıda bulunmaz.`,E:`Genetik anormallikler yanlış katlanmış protein birikimiyle hasar yapabilir.`},dogru:`D`,aciklama:`Enfeksiyöz ajanlar toksin üretimi, hücre içinde replikasyon ve aşırı/kronik bağışıklık yanıtı ile hasar verir.`,sik_aciklamalari:{A:`Doğru ifade; bunlar hasarın ana hedefleridir.`,B:`Doğru ifade; hedefler birbiriyle bağlantılıdır.`,C:`Doğru ifade; doz ve bireysel duyarlılık belirleyicidir.`,D:`Yanlış ifade (aranan cevap). Konak bağışıklık yanıtı da önemli bir hasar mekanizmasıdır.`,E:`Doğru ifade; fonksiyon kaybı/kazanımı da genetik mekanizmalardır.`},bilgi:[5,6,8,13],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q05`,kazanim:2,zorluk:`orta`,soru:`Göğüs ağrısıyla başvuran bir hastada koroner arterde trombüs saptanmış, miyokard bölgesinde kan akımı kesilmiştir. Hekim, bu tablonun hücre hasarının en sık nedenlerinden biri olduğunu belirtmektedir. Bu olgudaki hasar nedeni aşağıdakilerden hangisidir?`,secenekler:{A:`Koroner arter tıkanmasına bağlı miyokard iskemisi`,B:`Fizyolojik büyüme faktörü artışı`,C:`Normal oksijen satürasyonu ve perfüzyon`,D:`Dengeli beslenme ve yeterli vitamin alımı`,E:`Kontrollü hormonal uyarı`},dogru:`A`,aciklama:`Hipoksi-iskemi en sık hasar nedenlerindendir; iskemide oksijen-besin azalır, atıklar uzaklaştırılamaz. Toksinler, enfeksiyöz ajanlar, immün reaksiyonlar, genetik bozukluklar, beslenme dengesizlikleri ve fiziksel etkenler diğer başlıca nedenlerdir.`,sik_aciklamalari:{A:`Doğru. İskemi kan akımının azalmasıdır ve en sık hasar-nekroz nedenlerindendir.`,B:`Büyüme faktörleri adaptasyon ve rejenerasyonda rol oynar, hasar nedeni değildir.`,C:`Normal perfüzyon hasar nedeni değildir.`,D:`Dengeli beslenme koruyucudur.`,E:`Kontrollü hormonal uyarı fizyolojiktir.`},bilgi:[3,5,6],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q06`,kazanim:2,zorluk:`zor`,soru:`Kömür sobası yanan bir evde baygın bulunan hastada karbon monoksit zehirlenmesi düşünülmüş, ayrıca kullandığı ilacın yüksek dozda karaciğer hasarı yaptığı bilinmektedir. Hücre hasarı nedenleriyle ilgili ifadelerden hangisi doğrudur?`,secenekler:{A:`Karbon monoksit oksijen taşıma kapasitesini artırır`,B:`İlaçlar her dozda güvenlidir, hiçbir zaman toksik değildir`,C:`Enfeksiyöz ajanlar yalnızca mekanik basıyla hasar verir`,D:`Aşırı ve kronik immün yanıt sekonder doku hasarı yapabilir`,E:`Otoimmün reaksiyonlar dokuya hiçbir zaman zarar vermez`},dogru:`D`,aciklama:`Karbon monoksit hemoglobine bağlanarak oksijen taşımayı bozar ve hipoksiye yol açar; ilaçlar terapötik dozda güvenli iken yüksek dozda toksiktir. Enfeksiyöz ajanlar toksin üretimi ve replikasyonla, immün yanıt ise otoimmünite ve alerjiyle hasar verir.`,sik_aciklamalari:{A:`Karbon monoksit hemoglobine bağlanarak taşımayı bozar.`,B:`İlaçlar yüksek dozda veya duyarlı bireyde toksiktir.`,C:`Toksin üretimi, replikasyon ve immün yanıtla hasar verirler.`,D:`Doğru. Otoimmün hastalıklar ve alerjik reaksiyonlar inflamasyon ve sekonder doku hasarı yapar.`,E:`Otoimmün reaksiyonlar doku hasarının önemli nedenlerindendir.`},bilgi:[4,5,6,7],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q07`,kazanim:2,zorluk:`orta`,soru:`Hipoksi ile iskemi arasındaki farkı doğru veren seçenek hangisidir?`,secenekler:{A:`Hipoksi besin eksikliğidir`,B:`İskemi oksijen fazlalığıdır`,C:`İskemi oksijen-besin azlığı, atık birikimi`,D:`Hipoksi kan akımı artışıdır`,E:`İkisi aynı şeydir`},dogru:`C`,aciklama:`Hipokside oksijen azalırken iskemide kan akımının kesilmesiyle oksijen ve besin azalması birlikte olur, ayrıca metabolik atıklar uzaklaştırılamaz. Bu ikili yoksunluk ve atık birikimi, mitokondriyal ATP üretimini hızla durdurur. Bu yüzden iskemi, hücre hasarı ve nekrozun en sık nedenidir.`,sik_aciklamalari:{A:`Besin eksikliği iskeminin bileşenidir, hipoksi oksijen eksikliğidir.`,B:`İskemide oksijen azalır, artmaz.`,C:`Doğru. Kan akımı kesilmesi üçlü etki yapar: oksijen ve besin azalır, atıklar kalır.`,D:`Hipoksi oksijenlenme sorunudur, akım artışı değildir.`,E:`Tanım ve sonuçlar farklıdır.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q08`,kazanim:2,zorluk:`orta`,soru:`Hipoksinin başlıca nedenlerini doğru sıralayan seçenek hangisidir?`,secenekler:{A:`CO, iskemi, anemi, akciğer hastalığı`,B:`Hipertansiyon ve egzersiz`,C:`Vitamin fazlalığı ve obezite`,D:`Aşılar ve antibiyotikler`,E:`Uyku ve istirahat`},dogru:`A`,aciklama:`Karbon monoksit hemoglobine oksijenden çok daha yüksek afiniteyle bağlanır ve oksijenin taşınmasını engeller. Arter tıkanmaları dokuya kan götürmez, akciğer hastalıkları kanın oksijenlenmesini azaltır, anemi ise taşıyıcı hemoglobin miktarını düşürür. Şiddetli kan kaybı ve şokta ise perfüzyon yetersizliği doku hipoksisi yaratır.`,sik_aciklamalari:{A:`Doğru. Taşıma bozukluğu, akım kesilmesi ve oksijenlenme yetersizliği hipoksi nedenleridir.`,B:`Hipertansiyon ve egzersiz hipoksi nedeni değildir.`,C:`Bunlar beslenme dengesizliği grubuna girer.`,D:`Aşı ve antibiyotikler hasar nedeni değildir.`,E:`Uyku ve istirahat fizyolojik durumlardır.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q09`,kazanim:2,zorluk:`orta`,soru:`Klinik tıpta hücre hasarının ve nekrozun en sık karşılaşılan temel nedeni aşağıdakilerden hangisidir?`,secenekler:{A:`Genetik enzim polimorfizmi`,B:`Hipoksi ve iskemi (azalmış kan akımı ve oksijen yetersizliği)`,C:`Aşırı A vitamini alımı`,D:`Radyo dalgalarına maruz kalma`,E:`Böcek ısırması`},dogru:`B`,aciklama:`Hipoksi (oksijen azlığı) ve iskemi (kan akımının kesilmesi/azalması), koroner arter hastalığı, inme ve periferik vasküler hastalıklarda görüldüğü üzere tıpta en yaygın hücre hasarı nedenidir.`,sik_aciklamalari:{"A, C, D, E":`Nadir veya daha kısıtlı hasar nedenleridir.`,B:`Doğru. Hipoksi ve iskemi en sık görülen hücre hasarı ve nekroz etiyolojisidir.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q10`,kazanim:2,zorluk:`zor`,soru:`Hipoksi ile İskemi arasındaki patofizyolojik farklar değerlendirildiğinde aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Hipoksi dokuya kan gitmemesidir, iskemi ise sadece kanda hemoglobin azlığıdır.`,B:`İskemi; arteryel obstrüksiyon veya venöz göllenme nedeniyle dokuya gelen kan akımının kesilmesidir; bu nedenle iskemide sadece oksijen değil, glukoz gibi besin maddeleri de kesilir ve toksik metabolik atıklar (laktik asit) dokudan uzaklaştırılamaz. Dolayısıyla iskemi hipoksiden daha hızlı ve ağır hasar verir.`,C:`Hipokside hücreler anaerobik glikoliz yapamaz, iskemide sınırsız glikoliz yapar.`,D:`İskemi sadece venlerde, hipoksi sadece arterlerde görülür.`,E:`Hipoksi her zaman nekroza yol açarken iskemi asla hücre öldürmez.`},dogru:`B`,aciklama:`İskemide kan akımı durduğu için oksijen yokluğuna ek olarak besin maddesi gelmez ve doku içinde laktat birikir; anaerobik glikoliz hızla durur. Saf hipokside (örn. anemi veya solunum yetmezliği) kan akımı sürdüğü için glukoz taşınabilir ve atıklar yıkanabilir. Bu yüzden iskemik hasar saf hipoksik hasardan çok daha hızlı ve yıkıcıdır.`,sik_aciklamalari:{"A, C, D, E":`Fizyopatolojik açıdan yanlış ve temelsiz önermelerdir.`,B:`Doğru. İskemide kan akımı kesildiğinden glikoliz substratı tükenir ve atık birikir; hasar saf hipoksiden çok daha ağırdır.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q11`,kazanim:2,zorluk:`orta`,soru:`Bağışıklık sisteminin kendi dokularına karşı toleransını yitirerek otoantikorlar veya oto-reaktif T lenfositleri aracılığıyla doku hasarı oluşturduğu hücre hasarı etiyolojik grubu hangisidir?`,secenekler:{A:`Fiziksel etkenler`,B:`İmmünolojik reaksiyonlar (otoimmün hastalıklar)`,C:`Beslenme dengesizlikleri`,D:`Genetik poliploidi`,E:`Paraziter invazyon`},dogru:`B`,aciklama:`İmmünolojik reaksiyonlar (otoimmünite, hipersensitivite/alerji), bağışıklık sisteminin kontrolsüz aktivasyonu ile inflamatuar doku hasarına yol açan etiyolojik gruptur.`,sik_aciklamalari:{"A, C, D, E":`Farklı hasar etiyolojileridir.`,B:`Doğru. İmmünolojik mekanizmalar otoimmün doku hasarını tanımlar.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q12`,kazanim:2,zorluk:`zor`,soru:`Karbon monoksit (CO) zehirlenmesi, siyanür alımı veya yüksek doz parasetamol kullanımı hangi hücre hasarı nedenleri başlığı altında incelenir?`,secenekler:{A:`Fiziksel travmalar`,B:`Kimyasal ajanlar ve toksinler`,C:`Beslenme yetersizliği`,D:`Konjenital malformasyon sekansı`,E:`Spesifik olmayan mezenkimal displazi`},dogru:`B`,aciklama:`Toksinler ve kimyasal ajanlar; çevresel zehirler (CO, insektisit), yaşam tarzı toksinleri (alkol, sigara) ve terapötik doz aşımında toksik hale gelen ilaçları (parasetamol) kapsayan temel hücre hasarı kategorisidir.`,sik_aciklamalari:{"A, C, D, E":`Kimyasal toksisite ile uyuşmayan sınıflamalardır.`,B:`Doğru. CO, siyanür ve ilaçlar kimyasal/toksik etkenlerdir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q13`,kazanim:2,zorluk:`orta`,soru:`Dalgıçların su altından aniden yüzeye çıkması sonucu kanda çözünmüş nitrojen gazının mikro-kabarcıklar haline gelerek damarları tıkaması (dekompresyon hastalığı) hangi hücre hasarı grubuna girer?`,secenekler:{A:`Fiziksel etkenler (ani atmosferik basınç değişiklikleri)`,B:`Biyolojik bakteriyel hasar`,C:`Otoimmün reaksiyon`,D:`Genetik delesyon`,E:`Primer beslenme fazlalığı`},dogru:`A`,aciklama:`Mekanik travma, aşırı sıcak/soğuk, radyasyon, elektrik ve ani atmosferik basınç değişimleri 'fiziksel etkenler' grubunu oluşturur.`,sik_aciklamalari:{A:`Doğru. Basınç değişikliği fiziksel hasar kategorisindedir.`,"B, C, D, E":`Fiziksel basınçla ilgisiz etiyolojilerdir.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q14`,kazanim:2,zorluk:`kolay`,soru:`"Koagülatif nekroz" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,D:`Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,E:`Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,C:`Birçok hücre etkilendiğinde organ soluk görünür, turgoru artar, ağırlığı artabilir.`,A:`Bakteri, virüs, mantar ve parazitlerin tümü hasar verebilir.`},dogru:`B`,aciklama:`Doğru: En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,sik_aciklamalari:{B:`Doğru. En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,D:`Yanlış. Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,E:`Yanlış. Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,C:`Yanlış. Birçok hücre etkilendiğinde organ soluk görünür, turgoru artar, ağırlığı artabilir.`,A:`Yanlış. Bakteri, virüs, mantar ve parazitlerin tümü hasar verebilir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q15`,kazanim:2,zorluk:`orta`,soru:`"Fiziksel etkenler" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,C:`Hücre içi ve lökosit enzimleri ölü hücreleri sindirir; miyelin figürleri zar fosfolipidlerinden türer.`,E:`Nekroz kazara hücre ölümüdür, enerji yetersizliği/toksik hasara bağlıdır ve her zaman patolojiktir; apoptoz programlıdır ve fizyolojik-patolojik olabilir.`,D:`Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir.`,A:`Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`},dogru:`B`,aciklama:`Doğru: Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,sik_aciklamalari:{B:`Doğru. Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,C:`Yanlış. Hücre içi ve lökosit enzimleri ölü hücreleri sindirir; miyelin figürleri zar fosfolipidlerinden türer.`,E:`Yanlış. Nekroz kazara hücre ölümüdür, enerji yetersizliği/toksik hasara bağlıdır ve her zaman patolojiktir; apoptoz programlıdır ve fizyolojik-patolojik olabilir.`,D:`Yanlış. Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir.`,A:`Yanlış. Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`},bilgi:[10],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q16`,kazanim:2,zorluk:`orta`,soru:`"Sıvılaşma (likefaksiyon) nekrozu" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{B:`Doku tamamen erir ve viskoz sıvıya döner.`,C:`En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,A:`Sonuç etkenin türüne, süresine ve şiddetine bağlıdır.`,D:`Birçok hücre etkilendiğinde organ soluk görünür, turgoru artar, ağırlığı artabilir.`,E:`Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir.`},dogru:`B`,aciklama:`Doğru: Doku tamamen erir ve viskoz sıvıya döner.`,sik_aciklamalari:{B:`Doğru. Doku tamamen erir ve viskoz sıvıya döner.`,C:`Yanlış. En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,A:`Yanlış. Sonuç etkenin türüne, süresine ve şiddetine bağlıdır.`,D:`Yanlış. Birçok hücre etkilendiğinde organ soluk görünür, turgoru artar, ağırlığı artabilir.`,E:`Yanlış. Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k02-q17`,kazanim:2,zorluk:`zor`,soru:`"Sıvılaşma (likefaksiyon) nekrozu" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{C:`Doku tamamen erir ve viskoz sıvıya döner.`,B:`Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,A:`Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`,E:`Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,D:`Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`},dogru:`C`,aciklama:`Doğru: Doku tamamen erir ve viskoz sıvıya döner.`,sik_aciklamalari:{C:`Doğru. Doku tamamen erir ve viskoz sıvıya döner.`,B:`Yanlış. Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,A:`Yanlış. Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`,E:`Yanlış. Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,D:`Yanlış. Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`},bilgi:[30],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:3,metin:`Hücre hasarının sonucunu belirleyen faktörleri ve hücre tipine özgü duyarlılıkları açıklar.`,sorular:[{id:`k1-04-q08`,kazanim:3,zorluk:`kolay`,soru:`Hücre hasarının sonucunu belirleyen etken özellikleri aşağıdakilerin hangisinde birlikte verilmiştir?`,secenekler:{A:`Etkenin rengi, kokusu ve ağırlığı`,B:`Etkenin türü, süresi ve şiddeti`,C:`Hastanın kan grubu ve cinsiyeti`,D:`Hücrenin büyüklüğü ve şekli`,E:`Etkenin coğrafi kaynağı`},dogru:`B`,aciklama:`Hasarın sonucu etkenin türüne, süresine ve şiddetine bağlıdır; ayrıca hedef hücrenin tipi ve genetik zemin yanıtı etkiler.`,sik_aciklamalari:{A:`Bu özellikler hasarın sonucunu belirlemez.`,B:`Doğru. Aynı etken düşük dozda geri dönüşümlü, yüksek dozda ölümcül hasar yapabilir.`,C:`Kan grubu ve cinsiyet temel belirleyiciler arasında sayılmaz.`,D:`Hücrenin tipi ve durumu önemlidir; büyüklük-şekil belirleyici değildir.`,E:`Coğrafi kaynak hasarın sonucunu belirlemez.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-04-q09`,kazanim:3,zorluk:`orta`,soru:`Tam iskemiye maruz kalan dokularda geri dönüşümsüz hasarın gelişme süresi karşılaştırıldığında aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Kalp kası iskemiyi iskelet kasından daha uzun süre tolere eder.`,B:`İskelet kası ve kalp kası aynı sürede geri dönüşümsüz hasara uğrar.`,C:`Kalp kasında 20-30 dakikada geri dönüşümsüz hasar gelişebilirken iskelet kası 2-3 saat tolere edebilir.`,D:`İskelet kası 20-30 dakikada, kalp kası 2-3 saatte nekroza gider.`,E:`Hiçbir hücre tipi iskemiyi tolere edemez; hasar anında geri dönüşümsüzdür.`},dogru:`C`,aciklama:`Farklı hücre tipleri aynı strese farklı yanıt verir; metabolik gereksinimi yüksek kalp kası iskemiye çok daha duyarlıdır.`,sik_aciklamalari:{A:`Tersi doğrudur; kalp kası daha duyarlıdır.`,B:`Hücre tipine göre duyarlılık farklıdır.`,C:`Doğru. Metabolik gereksinimi yüksek kalp kası iskemiye çok daha duyarlıdır; iskelet kası 2-3 saat tolere edebilir.`,D:`Süreler ters verilmiştir.`,E:`Hücreler belirli bir süre iskemiyi geri dönüşümlü hasarla tolere edebilir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-04-q10`,kazanim:3,zorluk:`zor`,soru:`Aynı dozda bir ilacı alan iki hastadan birinde ciddi karaciğer hasarı gelişirken diğerinde hiçbir hasar görülmemiştir.

Bu farkı en iyi açıklayan durum aşağıdakilerden hangisidir?`,secenekler:{A:`Hasarın sonucu yalnızca etkenin türüne bağlıdır.`,B:`İlaçlar hiçbir koşulda hücre hasarı yapmaz.`,C:`Karaciğer hücreleri toksinlere karşı tamamen dirençlidir.`,D:`Toksin metabolizmasını etkileyen genetik polimorfizmler bireyin hasara duyarlılığını değiştirir.`,E:`Hasar yalnızca immünolojik nedenlerle oluşabilir.`},dogru:`D`,aciklama:`Hedef hücrenin durumu ve genetik zemin (polimorfizmler) toksin metabolizmasını ve hasar duyarlılığını etkiler.`,sik_aciklamalari:{A:`Etkenin türü, süresi ve şiddetinin yanında konak özellikleri de belirleyicidir.`,B:`İlaçlar yüksek dozda veya duyarlı bireyde toksik olabilir.`,C:`Hepatositler toksik hasara uğrayabilir.`,D:`Doğru. Bireysel genetik farklar aynı doza farklı yanıtı açıklar.`,E:`Toksik hasar immün mekanizma olmadan da gelişir.`},bilgi:[5,12],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q04`,kazanim:3,zorluk:`orta`,soru:`Aynı süreyle turnike uygulanan iki dokudan kalp kasında yaygın nekroz gelişirken iskelet kasında yalnızca geri dönüşümlü değişiklikler izlenmiştir. Ayrıca düşük dozda yalnızca şişme yapan bir toksinin yüksek dozda nekroz yaptığı bilinmektedir. Bu gözlemlerle ilgili ifadelerden hangisi doğrudur?`,secenekler:{A:`Hasarın sonucu yalnızca etkenin türüne bağlıdır, doz ve süre önemsizdir`,B:`Aynı etken düşük dozda geri dönüşümlü hasar, yüksek dozda nekroz yapabilir`,C:`Tüm hücre tipleri iskemiye eşit dayanıklılık gösterir`,D:`Genetik zemin toksin duyarlılığını hiçbir şekilde etkilemez`,E:`Kalp kası iskelet kasından daha uzun iskemi tolere eder`},dogru:`B`,aciklama:`Sonuç etkenin türü, süresi ve şiddetine bağlıdır; aynı etken düşük dozda geri dönüşümlü hasar, yüksek dozda nekroz yapar. Farklı hücre tipleri aynı strese farklı yanıt verir; kalp kası iskemiye iskelet kasından daha duyarlıdır.`,sik_aciklamalari:{A:`Tür, süre ve şiddet birlikte belirleyicidir.`,B:`Doğru. Doz-yanıt ilişkisi hasarın temel ilkesidir.`,C:`Hücre tipine özgü duyarlılık vardır.`,D:`Genetik polimorfizmler toksin metabolizmasını etkiler.`,E:`Kalp kası 20-30 dakika, iskelet kası 2-3 saat iskemiyi tolere eder.`},bilgi:[11,12],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q05`,kazanim:3,zorluk:`zor`,soru:`Ailesel enzim polimorfizmi nedeniyle standart dozda bir ilacı toksik düzeyde metabolize eden bir hastada karaciğer nekrozu gelişmiş, aynı dozu alan diğer bireylerde hasar görülmemiştir. Hücre tipine özgü duyarlılık ve genetik zeminle ilgili ifadelerden hangisi doğrudur?`,secenekler:{A:`Nöronlar iskemiye karaciğerden daha dayanıklıdır`,B:`İskelet kası kalpten daha kısa iskemi tolere eder`,C:`Hücresel hedefler arasında mitokondri ve zarlar yer almaz`,D:`Aynı toksine tüm bireyler aynı yanıtı verir`,E:`Genetik polimorfizmler toksin metabolizmasını etkileyerek duyarlılığı değiştirir`},dogru:`E`,aciklama:`İskelet kası 2-3 saat, kalp kası 20-30 dakika iskemiyi tolere eder; bu fark metabolik hız ve enerji rezervleriyle ilişkilidir. Genetik polimorfizmler toksin metabolizmasını ve hasar duyarlılığını etkiler.`,sik_aciklamalari:{A:`Nöronlar iskemiye en duyarlı hücrelerdendir.`,B:`İskelet kası 2-3 saat, kalp kası 20-30 dakika tolere eder.`,C:`Zarlar, mitokondri, protein sentez mekanizması ve DNA ana hedeflerdir.`,D:`Genetik zemin bireysel duyarlılığı belirler.`,E:`Doğru. Genetik zemin aynı toksine farklı yanıtı açıklar.`},bilgi:[12,13],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q06`,kazanim:3,zorluk:`orta`,soru:`Hücre hasarının sonucunu belirleyen üç faktör nedir?`,secenekler:{A:`Yalnızca etken türü`,B:`Yalnızca hasta yaşı`,C:`Yalnızca cinsiyet`,D:`Yalnızca mevsim`,E:`Etken türü, süresi, şiddeti`},dogru:`E`,aciklama:`Düşük dozda aynı etken yalnızca geri dönüşümlü hasar yaparken, doz artınca geri dönüşümsüz hasar ve ölüm gelişir. Süre uzadıkça biriken mitokondriyal ve zar hasarı eşiği aşar. Bu doz-süre ilişkisi, toksikolojide ve iskemi yönetiminde terapötik pencerenin temelidir.`,sik_aciklamalari:{A:`Tür tek başına yetmez, doz ve süre belirleyicidir.`,B:`Yaş duyarlılığı etkiler ancak üç ana faktörden biri değildir.`,C:`Cinsiyet ana belirleyici değildir.`,D:`Mevsimin hasar sonucuyla ilişkisi yoktur.`,E:`Doğru. Sonuç bu üç faktörün bileşimine bağlıdır.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q07`,kazanim:3,zorluk:`orta`,soru:`Tam iskemiye kalp ve iskelet kası toleransı nasıldır?`,secenekler:{A:`İkisi de 2-3 saat dayanır`,B:`Kalp 20-30 dakika, iskelet 2-3 saat`,C:`Kalp sınırsız dayanır`,D:`İskelet daha duyarlıdır`,E:`Fark yoktur`},dogru:`B`,aciklama:`Kalp kası sürekli aerobik metabolizmaya bağımlıdır ve glikojen deposu sınırlıdır, bu yüzden tam iskemide 20-30 dakikada geri dönüşümsüz hasar gelişir. İskelet kası ise glikojen deposu ve anaerobik glikoliz kapasitesiyle 2-3 saat dayanabilir. Genetik polimorfizmler de toksin metabolizma hızını değiştirerek bireysel duyarlılığı etkiler.`,sik_aciklamalari:{A:`Kalp kası çok daha kısa sürede hasarlanır.`,B:`Doğru. Metabolik bağımlılık ve depo farkı toleransı belirler.`,C:`Kalp iskemiye en duyarlı dokulardandır.`,D:`İskelet kası daha dayanıklıdır.`,E:`Doku duyarlılıkları belirgin farklıdır.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q08`,kazanim:3,zorluk:`orta`,soru:`Zedeleyici bir etken karşısında hasarın hafif mi, geri dönüşümlü mü yoksa ölümcül mü olacağını belirleyen etkene ait üç temel özellik hangisidir?`,secenekler:{A:`Etkenin rengi, kokusu ve tadı`,B:`Etkenin türü (doğası), şiddeti (dozu) ve maruziyet süresi`,C:`Etkenin ağırlığı, hacmi ve parlaklığı`,D:`Etkenin mikroskop altındaki büyütme gücü`,E:`Etkenin maliyeti ve laboratuvara geliş saati`},dogru:`B`,aciklama:`Hasarın şiddetini belirleyen etkene ait temel değişkenler: türü, dozu/şiddeti ve hücreyle temas süresidir.`,sik_aciklamalari:{"A, C, D, E":`Tıbbi parametreler değildir.`,B:`Doğru. Tür, şiddet (doz) ve süre hücresel yanıtın ana belirleyicisidir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q09`,kazanim:3,zorluk:`zor`,soru:`Akut tam arteriyel iskemiye maruz kalan dokuların hipoksiye duyarlılıkları karşılaştırıldığında geri dönüşümsüz hasar gelişme süresi en kısa olan hücre tipi hangisidir?`,secenekler:{A:`Santral sinir sistemi nöronları (3-5 dakika)`,B:`Kardiyak ventrikül miyositleri (20-30 dakika)`,C:`İskelet kası lifleri (2-3 saat)`,D:`Deri fibroblastları ve bağ dokusu (saatlerce)`,E:`Kemik osteositleri (24 saat)`},dogru:`A`,aciklama:`Farklı hücrelerin iskemiye dayanıklılığı çok farklıdır: Serebral korteks nöronları oksijensizliğe yalnızca 3-5 dakika dayanabilir; sonrasında geri dönüşümsüz nekroza gider. Miyositler 20-30 dakika, iskelet kası ise 2-3 saat iskemiye tolere edebilir.`,sik_aciklamalari:{A:`Doğru. Nöronlar en yüksek metabolizmaya sahip olup 3-5 dakikada geri dönüşümsüz hasara uğrar.`,"B, C, D, E":`Nöronlara göre iskemiye belirgin derecede daha dirençlidirler.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q10`,kazanim:3,zorluk:`orta`,soru:`İskelet kası dokusu tam arteriyel iskemiye kaç saat boyunca geri dönüşümsüz hasar gelişmeden direnç gösterebilir?`,secenekler:{A:`Sadece 10 saniye`,B:`Yaklaşık 2-3 saat`,C:`Tam olarak 3 hafta`,D:`Asla dayanamaz, anında erir`,E:`5 gün`},dogru:`B`,aciklama:`İskelet kası hücreleri düşük istirahat metabolizması ve zengin glikojen deposu sayesinde tam iskemiye 2-3 saat boyunca tolere edebilir (örneğin cerrahi turnike uygulamalarında).`,sik_aciklamalari:{"A, D":`İskelet kası son derece dirençlidir, saniyelerde ölmez.`,B:`Doğru. İskelet kası 2-3 saat iskemiye dayanabilir.`,"C ve E":`Gerçek dışı uzun sürelerdir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q11`,kazanim:3,zorluk:`zor`,soru:`Aynı doz toksik ilaca maruz kalan iki farklı hastadan birinde ağır karaciğer nekrozu gelişirken diğerinde hiçbir hasar oluşmamasının temel moleküler gerekçesi nedir?`,secenekler:{A:`İlacın hastanın giysisine dökülmesi`,B:`Sitokrom P450 enzim sistemlerindeki genetik polimorfizmler nedeniyle ilacın reaktif toksik metabolitlere dönüşme hızının bireyler arasında farklılık göstermesi`,C:`Birinci hastanın daha kısa boylu olması`,D:`Karaciğerin sağ lobunun sola göre toksinleri sevmemesi`,E:`Formalin kokusunun ilacı aktive etmesi`},dogru:`B`,aciklama:`Genetik polimorfizmler (özellikle CYP2E1, CYP2D6 vb. karaciğer mikrozomal enzimleri) toksinlerin detoksifikasyon veya toksik ara ürünlere dönüşüm hızını belirleyerek bireysel hasar duyarlılığını tayin eder.`,sik_aciklamalari:{"A, C, D, E":`Bilimsel temeli olmayan seçeneklerdir.`,B:`Doğru. Sitokrom P450 genetik polimorfizmleri bireysel toksin duyarlılığının ana nedenidir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q12`,kazanim:3,zorluk:`orta`,soru:`Bir dokudaki hücrelerin farklılaşma (diferansiasyon) ve bölünme kapasitelerinin hasara yanıt üzerindeki etkisi ile ilgili hangisi doğrudur?`,secenekler:{A:`Bölünme yeteneği olmayan kalıcı hücreler (kalp kası, nöron) hasara uğrayıp öldüğünde doku rejenerasyonla kendini tamir edemez, kayıp fibröz skar ile onarılır.`,B:`Kalıcı hücreler öldüğünde 1 günde mitoz bölünme ile yerine yenisi gelir.`,C:`Labil hücreler hasara uğradığında asla yenilenemez.`,D:`Bütün organlar hasar karşısında eşit oranda kök hücre üretir.`,E:`Hücre diferansiasyonunun hasarla hiçbir ilgisi yoktur.`},dogru:`A`,aciklama:`Kalıcı (permanent) hücreler kaybedildiğinde rejenerasyon gerçekleşemez; doku kaybı bağ dokusu artışı (skar/fibrozis) ile kapatılır.`,sik_aciklamalari:{A:`Doğru. Kalıcı hücre kaybı skar ile sonuçlanır.`,B:`Kalıcı hücreler mitoz bölünme yapamaz.`,C:`Labil hücreler sürekli bölünen ve kendini yenileyen hücrelerdir.`,"D ve E":`Biyolojik olarak yanlıştır.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q13`,kazanim:3,zorluk:`kolay`,soru:`"Beyin infarktı istisnası" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{E:`İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`,B:`Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,A:`Hipoksi oksijen eksikliği, iskemi kan akımının azalması veya kesilmesidir.`,C:`Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,D:`En erken geri dönüşümlü hasar bulgusudur; ATP eksikliği ile Na⁺/K⁺ ATPaz pompası bozulur.`},dogru:`E`,aciklama:`Doğru: İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`,sik_aciklamalari:{E:`Doğru. İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`,B:`Yanlış. Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,A:`Yanlış. Hipoksi oksijen eksikliği, iskemi kan akımının azalması veya kesilmesidir.`,C:`Yanlış. Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,D:`Yanlış. En erken geri dönüşümlü hasar bulgusudur; ATP eksikliği ile Na⁺/K⁺ ATPaz pompası bozulur.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q14`,kazanim:3,zorluk:`orta`,soru:`"Geri dönüşümsüzlük kriterleri" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{D:`Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,B:`Hücrenin normal homeostazını koruyamadığı durumdur.`,C:`Sağlıklı hücre → zararlı uyaran → geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü (nekroz/apoptoz).`,E:`Hücre içi ve lökosit enzimleri ölü hücreleri sindirir; miyelin figürleri zar fosfolipidlerinden türer.`,A:`En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`},dogru:`D`,aciklama:`Doğru: Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,sik_aciklamalari:{D:`Doğru. Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,B:`Yanlış. Hücrenin normal homeostazını koruyamadığı durumdur.`,C:`Yanlış. Sağlıklı hücre → zararlı uyaran → geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü (nekroz/apoptoz).`,E:`Yanlış. Hücre içi ve lökosit enzimleri ölü hücreleri sindirir; miyelin figürleri zar fosfolipidlerinden türer.`,A:`Yanlış. En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q15`,kazanim:3,zorluk:`orta`,soru:`"Nekrozun sitoplazmik değişiklikleri" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Artmış eozinofili (denatüre proteinlere eozin bağlanması, RNA kaybı), camsı homojen görünüm ve vakuolizasyon.`,B:`Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,E:`Birçok hücre etkilendiğinde organ soluk görünür, turgoru artar, ağırlığı artabilir.`,D:`Koagülatif, sıvılaşma (likefaksiyon), gangrenöz, kazeöz, yağ ve fibrinoid nekroz.`,C:`Farklı hücre tipleri aynı strese farklı yanıt verir; iskelet kası 2-3 saat, kalp kası 20-30 dakika iskemiyi tolere eder.`},dogru:`A`,aciklama:`Doğru: Artmış eozinofili (denatüre proteinlere eozin bağlanması, RNA kaybı), camsı homojen görünüm ve vakuolizasyon.`,sik_aciklamalari:{A:`Doğru. Artmış eozinofili (denatüre proteinlere eozin bağlanması, RNA kaybı), camsı homojen görünüm ve vakuolizasyon.`,B:`Yanlış. Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,E:`Yanlış. Birçok hücre etkilendiğinde organ soluk görünür, turgoru artar, ağırlığı artabilir.`,D:`Yanlış. Koagülatif, sıvılaşma (likefaksiyon), gangrenöz, kazeöz, yağ ve fibrinoid nekroz.`,C:`Yanlış. Farklı hücre tipleri aynı strese farklı yanıt verir; iskelet kası 2-3 saat, kalp kası 20-30 dakika iskemiyi tolere eder.`},bilgi:[24],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k03-q16`,kazanim:3,zorluk:`zor`,soru:`"Beslenme dengesizlikleri" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{C:`Yetersiz alım (protein-kalori malnütrisyonu, vitamin eksiklikleri) ve aşırı alım (obezite, tip 2 diyabet, ateroskleroz).`,D:`Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,B:`Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,A:`Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,E:`Nekroz kazara hücre ölümüdür, enerji yetersizliği/toksik hasara bağlıdır ve her zaman patolojiktir; apoptoz programlıdır ve fizyolojik-patolojik olabilir.`},dogru:`C`,aciklama:`Doğru: Yetersiz alım (protein-kalori malnütrisyonu, vitamin eksiklikleri) ve aşırı alım (obezite, tip 2 diyabet, ateroskleroz).`,sik_aciklamalari:{C:`Doğru. Yetersiz alım (protein-kalori malnütrisyonu, vitamin eksiklikleri) ve aşırı alım (obezite, tip 2 diyabet, ateroskleroz).`,D:`Yanlış. Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,B:`Yanlış. Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,A:`Yanlış. Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,E:`Yanlış. Nekroz kazara hücre ölümüdür, enerji yetersizliği/toksik hasara bağlıdır ve her zaman patolojiktir; apoptoz programlıdır ve fizyolojik-patolojik olabilir.`},bilgi:[9],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:4,metin:`Geri dönüşümlü hücre hasarının morfolojik özelliklerini açıklar.`,sorular:[{id:`k1-04-q11`,kazanim:4,zorluk:`kolay`,soru:`Geri dönüşümlü hücre hasarının ışık mikroskobunda görülen en erken bulgusu aşağıdakilerden hangisidir?`,secenekler:{A:`Karyoreksis`,B:`Hücresel şişme (hidropik değişim)`,C:`Distrofik kalsifikasyon`,D:`Karyolizis`,E:`Koagülasyon nekrozu`},dogru:`B`,aciklama:`Hücresel şişme en erken geri dönüşümlü hasar bulgusudur; ATP eksikliğine bağlı Na⁺/K⁺ ATPaz pompasının bozulmasıyla oluşur.`,sik_aciklamalari:{A:`Karyoreksis nekrozun nükleer değişikliğidir.`,B:`Doğru. ER dilatasyonuna karşılık gelen berrak vakuoller görülür.`,C:`Distrofik kalsifikasyon nekrotik dokuda gelişir.`,D:`Karyolizis nekrozun nükleer değişikliğidir.`,E:`Koagülasyon nekrozu geri dönüşümsüz hasardır.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-04-q12`,kazanim:4,zorluk:`orta`,soru:`Hücresel şişmenin (hidropik değişim) mekanizması aşağıdakilerden hangisidir?`,secenekler:{A:`ATP eksikliğine bağlı Na⁺/K⁺ ATPaz pompasının bozulması ve hücre içine su girişi`,B:`Trigliseridlerin sitoplazmada birikmesi`,C:`Kaspazların aktive olması`,D:`Çekirdeğin büzülüp bazofilisinin artması`,E:`Hücre zarının tamamen parçalanması`},dogru:`A`,aciklama:`ATP azalınca Na⁺/K⁺ pompası çalışamaz; hücre içinde sodyum ve su birikir, ER dilate olur ve sitoplazmada berrak vakuoller oluşur.`,sik_aciklamalari:{A:`Doğru. ATP azalınca pompa durur, hücre içinde Na⁺ ve su birikir, hücre şişer.`,B:`Bu yağlanmanın (steatoz) tanımıdır.`,C:`Kaspaz aktivasyonu apoptoz mekanizmasıdır.`,D:`Bu piknozdur; nekrozun nükleer değişikliğidir.`,E:`Zarın parçalanması geri dönüşümsüz hasarın (nekroz) özelliğidir; geri dönüşümlü hasarda membran bütünlüğü korunur.`},bilgi:[17,14],benzer_cikmis:[]},{id:`k1-04-q13`,kazanim:4,zorluk:`orta`,soru:`Aşağıdakilerden hangisi geri dönüşümlü hücre hasarının özelliklerinden biri değildir?`,secenekler:{A:`Plazma zarında kabarcıklanma ve mikrovillus kaybı`,B:`Endoplazmik retikulum dilatasyonu ve ribozomların ayrılması`,C:`Yağlanma`,D:`Miyelin figürleri`,E:`Mitokondrilerde kalsiyum içeren elektron yoğun birikintiler`},dogru:`E`,aciklama:`Mitokondrilerde belirgin şişme ve kalsiyum-protein içeren elektron yoğun birikintiler geç, geri dönüşümsüz hasarın bulgusudur.`,sik_aciklamalari:{A:`Geri dönüşümlü hasarda görülür.`,B:`Geri dönüşümlü hasarda görülür.`,C:`Geri dönüşümlü hasarda görülür; özellikle karaciğer ve kalpte.`,D:`Geri dönüşümlü hasarda da görülebilir; zar fosfolipidlerinden türer.`,E:`Geri dönüşümlü hasarın özelliği değildir (aranan cevap); hücre ölümünün yaklaştığını gösterir.`},bilgi:[16,21],benzer_cikmis:[]},{id:`k1-04-q14`,kazanim:4,zorluk:`zor`,soru:`İskemik hasar sonrası çok sayıda hücresinde hidropik değişim gelişmiş bir organın makroskobik görünümü için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Organ küçülür, sertleşir ve kahverengi görünür.`,B:`Organ soluk görünür, turgoru artar ve ağırlığı artabilir.`,C:`Organ sıvılaşır ve viskoz bir kitleye dönüşür.`,D:`Organda kama şeklinde, sarı ve kenarı belirgin bir alan oluşur.`,E:`Organ yüzeyinde tebeşir beyazı kalsifik plaklar oluşur.`},dogru:`B`,aciklama:`Hücresel şişme birçok hücreyi etkilediğinde organ soluk, gergin (turgoru artmış) ve daha ağır görünür.`,sik_aciklamalari:{A:`Küçülme atrofiye uyar; hidropik değişim organı büyütür.`,B:`Doğru. Şişen hücreler organı soluk, gergin ve ağır gösterir.`,C:`Sıvılaşma likefaksiyon nekrozunun görünümüdür.`,D:`Kama şeklinde sarı alan koagülatif nekroz (enfarkt) görünümüdür.`,E:`Kalsifik plaklar kalsifikasyonun bulgusudur.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q05`,kazanim:4,zorluk:`orta`,soru:`Hipoksiye maruz kalan karaciğer biyopsisinde hepatositlerde berrak sitoplazmik vakuoller ve sitoplazmada trigliserid damlacıkları izlenmiş, hücre zarları sağlam bulunmuştur. Uyarı kaldırılınca hücrelerin normale dönebileceği belirtilmiştir. Bu tablodaki morfolojik bulgular aşağıdakilerden hangisidir?`,secenekler:{A:`Hücresel şişme ve yağlanma`,B:`Piknoz, karyoreksis ve karyolizis`,C:`Zar parçalanması ve içerik sızıntısı`,D:`Doku mimarisinin tamamen kaybı`,E:`Çekirdeğin 1-2 günde tamamen kaybolması`},dogru:`A`,aciklama:`Hücresel şişme en erken geri dönüşümlü hasar bulgusudur; ATP eksikliğiyle Na⁺/K⁺ ATPaz bozulur, su giriş olur ve ER dilatasyonuna karşılık gelen berrak sitoplazmik vakuoller görülür. Yağlanma trigliserid birikimidir ve en sık karaciğer ile kalpte görülür.`,sik_aciklamalari:{A:`Doğru. Şişme ve yağlanma geri dönüşümlü hasarın klasik morfolojisidir.`,B:`Bunlar nekrozun nükleer değişiklikleridir.`,C:`Zar parçalanması geri dönüşümsüzlüğü gösterir.`,D:`Mimari kaybı nekroz bulgusudur.`,E:`Çekirdek kaybı nekrozda izlenir.`},bilgi:[16,17,19],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q06`,kazanim:4,zorluk:`zor`,soru:`Akut kan kaybı sonrası böbrek biyopsisinde tübül epitelinde yaygın berrak sitoplazmik vakuolizasyon izlenmiş, böbrek makroskopide soluk ve ödemli bulunmuştur. Elektron mikroskopta endoplazmik retikulumda genişleme görülmüştür. Bu tabloyla ilgili ifadelerden hangisi doğrudur?`,secenekler:{A:`Organ küçülür, koyulaşır ve sertleşir`,B:`Hücresel şişmede membran bütünlüğü her zaman bozulur`,C:`Berrak vakuoller mitokondriyal kalsiyum birikimine karşılık gelir`,D:`Etkilenen organ soluk görünür, turgoru ve ağırlığı artar`,E:`Hidropik değişim geri dönüşümsüz hasarın bulgusudur`},dogru:`D`,aciklama:`Birçok hücre etkilendiğinde organ soluk görünür, turgoru ve ağırlığı artar; bu hidropik değişimin makroskobik karşılığıdır. Işık mikroskobunda berrak vakuoller ER dilatasyonuna karşılık gelir ve membran bütünlüğü korunur.`,sik_aciklamalari:{A:`Bu nekrozun makroskobik özelliklerine uyar; şişmede organ soluk ve ödemlidir.`,B:`Geri dönüşümlü hasarda membran bütünlüğü korunur.`,C:`Berrak vakuoller ER dilatasyonuna karşılık gelir.`,D:`Doğru. Hidropik değişimde su tutulumu organı soldurur ve ağırlaştırır.`,E:`Hidropik değişim geri dönüşümlü hasarın klasik örneğidir.`},bilgi:[17,18,14],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q07`,kazanim:4,zorluk:`orta`,soru:`Hücresel şişmenin (hidropik değişim) mekanizması nedir?`,secenekler:{A:`Karyoreksis ve piknoz`,B:`Zar rüptürü ve inflamasyon`,C:`Mitokondride kalsiyum çökmesi`,D:`ATP azalması, pompa yetmezliği, su girişi`,E:`DNA parçalanması`},dogru:`D`,aciklama:`ATP eksikliğinde Na⁺/K⁺ ATPaz pompası durur, hücre içine giren sodyum ozmotik olarak suyu çeker. Su önce endoplazmik retikulum sisterlarına dolarak berrak sitoplazmik vakuoller oluşturur. Birçok hücre etkilendiğinde organ soluk görünür, turgoru ve ağırlığı artar; uyaran kalkarsa tablo düzelir.`,sik_aciklamalari:{A:`Bunlar geri dönüşümsüz nekrozun nükleer bulgularıdır.`,B:`Zar rüptürü ve inflamasyon nekrozun özelliğidir.`,C:`Kalsiyum çökmesi geç hasarın mitokondriyal bulgusudur.`,D:`Doğru. Pompa yetmezliği ozmotik su girişine ve ER dilatasyonuna yol açar.`,E:`DNA parçalanması geri dönüşümsüzlük kriteridir.`},bilgi:[17,18],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q08`,kazanim:4,zorluk:`orta`,soru:`Yağlanmanın (steatoz) içeriği ve en sık görüldüğü organlar nedir?`,secenekler:{A:`Trigliserid birikimi, karaciğer ve kalp`,B:`Kalsiyum birikimi, böbrek`,C:`Demir birikimi, dalak`,D:`Amiloid birikimi, beyin`,E:`Melanin birikimi, deri`},dogru:`A`,aciklama:`Trigliseridlerin sitoplazmik vakuollerde birikimi en sık karaciğer ve kalp kasında görülür. Alkol yağ asidi oksidasyonunu bozar, obezite ve diyabet yağ asidi sunumunu artırır, hipoksi ve toksinler lipoprotein sentezini aksatır. Uyaran kaldırılırsa biriken yağ mobilize edilir ve hücre normale döner.`,sik_aciklamalari:{A:`Doğru. Yağ metabolizması bozukluğu bu iki organda steatoz yapar.`,B:`Kalsiyum birikimi distrofik kalsifikasyondur, yağlanma değildir.`,C:`Demir birikimi hemosiderozdur.`,D:`Amiloid protein birikimidir.`,E:`Melanin pigment birikimidir.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q09`,kazanim:4,zorluk:`orta`,soru:`Geri dönüşümlü hücre hasarında ortaya çıkan en erken ve evrensel morfolojik bulgu olan 'hücresel şişme'nin (hidropik dejenerasyon) patogenetik mekanizması nedir?`,secenekler:{A:`Hücre zarındaki kolesterolün tamamen erimesi`,B:`Mitokondriyal ATP sentezinin azalması sonucu plazma zarında bulunan enerji bağımlı Na+/K+ ATPaz iyon pompasının durması; hücre içinde sodyum ve suyun birikmesi`,C:`Hücre çekirdeğinin parçalanması`,D:`DNA'nın aşırı metillenmesi`,E:`Dışarıdan dokuya kanama olması`},dogru:`B`,aciklama:`Hipoksi ve enerji azlığında Na+/K+ pompası durur. Sodyum hücre dışına pompalanamaz, hücre içine girer; ozmotik olarak suyu çeker ve hücre şişer (hücresel şişme / hidropik değişim).`,sik_aciklamalari:{"A, C, D, E":`Hücresel şişmenin primer mekanizması değildir.`,B:`Doğru. Na+/K+ pompa yetmezliği sonucu intraselüler Na+ ve su birikimi hücresel şişmenin temelidir.`},bilgi:[10,11],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q10`,kazanim:4,zorluk:`zor`,soru:`Geri dönüşümlü hücre hasarı sürecindeki bir hücre elektron mikroskobu (EM) düzeyinde incelendiğinde aşağıdaki ultrastrüktürel değişikliklerden hangisi beklenmez?`,secenekler:{A:`Plazma zarında kabarcıklanmalar (blebs) ve mikrovillusların silinmesi`,B:`Mitokondrilerde hafif şişme ve endoplazmik retikulumda genişleme (dilatasyon)`,C:`Ribozomların granüler endoplazmik retikulum yüzeyinden ayrılması (detachment)`,D:`Plazma zarında geniş devamlılık kayıpları ve mitokondrilerde büyük amorf kalsiyum yoğunlukları birikimi`,E:`Sitoplazmada fosfolipid membran artıklarından oluşan miyelin figürleri`},dogru:`D`,aciklama:`Plazma zarında geniş yırtıklar/süreksizlikler ve mitokondri matriksinde kalsiyum içeren büyük amorf elektron-yoğun birikintiler GERİ DÖNÜŞÜMSÜZ hasarın (nekroz) kesin kriterleridir; geri dönüşümlü evrede görülmez.`,sik_aciklamalari:{"A, B, C, E":`Geri dönüşümlü hücre hasarının klasik ultrastrüktürel bulgularıdır.`,D:`Doğru (beklenmez). Membran parçalanması ve amorf mitokondriyal yoğunluklar geri dönüşümsüz nekroza aittir.`},bilgi:[10,12],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q11`,kazanim:4,zorluk:`orta`,soru:`Bir organın (örneğin böbrek veya karaciğer) parankim hücrelerinin tamamında yaygın hidropik dejenerasyon (hücresel şişme) geliştiğinde organın makroskobik görünümü nasıl etkilenir?`,secenekler:{A:`Organ simsiyah renk alır ve taş gibi sertleşir.`,B:`Organ soluklaşır, parankim sıkışmasına bağlı turgoru artar, kenarları yuvarlaklaşır ve ağırlığı artar.`,C:`Organ tamamen sıvılaşarak erir.`,D:`Organ hacmi yarı yarıya küçülür ve buruşur.`,E:`Organ şeffaflaşır.`},dogru:`B`,aciklama:`Hücreler su alıp şiştiğinde kılcal damarları komprese eder; bu yüzden organ soluklaşır, kapsülü gerilir (turgor artışı) ve toplam su içeriği nedeniyle ağırlığı artar.`,sik_aciklamalari:{"A, C, D, E":`Şişmiş organın makroskopik özellikleri değildir.`,B:`Doğru. Solukluk, artmış turgor ve ağırlık artışı hücresel şişmenin makroskopik tablosudur.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q12`,kazanim:4,zorluk:`orta`,soru:`Geri dönüşümlü hücre hasarında görülen 'yağlanma' (steatoz / fatty change) en sık hangi organda izlenir ve ışık mikroskobik özelliği nedir?`,secenekler:{A:`Beyin parankiminde nöronal vakuoller`,B:`Karaciğer hepatosit sitoplazmasında berrak lipid trigliserid vakuollerinin birikmesi`,C:`Kemikte kalsiyum erimesi`,D:`Dalakta beyaz pulpa büyümesi`,E:`Deri epidermisinin kalınlaşması`},dogru:`B`,aciklama:`Yağ metabolizmasının merkezi olan karaciğerde (ve miyokartta) toksik, hipoksik veya metabolik hasarda trigliseridler atılamaz ve sitoplazmada vakuoller oluşturarak birikir (steatoz).`,sik_aciklamalari:{"A, C, D, E":`Steatozun tipik morfolojisi ve hedefi değildir.`,B:`Doğru. Karaciğerde trigliserid birikimi klasik yağlanma tablosudur.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q13`,kazanim:4,zorluk:`zor`,soru:`Geri dönüşümlü hasarda protein sentezinin hızla düşmesinin hücresel elektron mikroskobik karşılığı olan yapısal değişiklik hangisidir?`,secenekler:{A:`Golgi cisimciğinin çekirdeğe girmesi`,B:`Ribozomların granüler endoplazmik retikulum membranından ayrılması (ribosomal detachment)`,C:`Lizozomların kendi kendini yutması`,D:`Mitokondrilerin kristalarının iki katına çıkması`,E:`Sentrozomların yok olması`},dogru:`B`,aciklama:`ATP düşüklüğü ve iyon dengesizliği sonucu granüllü endoplazmik retikulum şişer ve üzerindeki ribozomlar sitoplazmaya dökülür (detachment); bu durum protein sentezinin çökmesine neden olur.`,sik_aciklamalari:{"A, C, D, E":`Hücresel zedelenmeyle ilgisiz yanlış biyolojik durumlardır.`,B:`Doğru. Ribozomların ER'den ayrılması protein sentezi düşüşünün morfolojik kanıtıdır.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q14`,kazanim:4,zorluk:`kolay`,soru:`"Geri dönüşümlü hasar tanımı" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{E:`Zararlı uyarı kaldırıldığında hücrenin normale dönebildiği durumdur.`,B:`Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,A:`En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,D:`Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`,C:`En erken geri dönüşümlü hasar bulgusudur; ATP eksikliği ile Na⁺/K⁺ ATPaz pompası bozulur.`},dogru:`E`,aciklama:`Doğru: Zararlı uyarı kaldırıldığında hücrenin normale dönebildiği durumdur.`,sik_aciklamalari:{E:`Doğru. Zararlı uyarı kaldırıldığında hücrenin normale dönebildiği durumdur.`,B:`Yanlış. Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,A:`Yanlış. En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,D:`Yanlış. Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`,C:`Yanlış. En erken geri dönüşümlü hasar bulgusudur; ATP eksikliği ile Na⁺/K⁺ ATPaz pompası bozulur.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q15`,kazanim:4,zorluk:`orta`,soru:`"Hücresel şişme (hidropik değişim)" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{E:`En erken geri dönüşümlü hasar bulgusudur; ATP eksikliği ile Na⁺/K⁺ ATPaz pompası bozulur.`,C:`Koagülatif, sıvılaşma (likefaksiyon), gangrenöz, kazeöz, yağ ve fibrinoid nekroz.`,D:`Bakteri, virüs, mantar ve parazitlerin tümü hasar verebilir.`,A:`Artmış eozinofili (denatüre proteinlere eozin bağlanması, RNA kaybı), camsı homojen görünüm ve vakuolizasyon.`,B:`Zararlı uyarı kaldırıldığında hücrenin normale dönebildiği durumdur.`},dogru:`E`,aciklama:`Doğru: En erken geri dönüşümlü hasar bulgusudur; ATP eksikliği ile Na⁺/K⁺ ATPaz pompası bozulur.`,sik_aciklamalari:{E:`Doğru. En erken geri dönüşümlü hasar bulgusudur; ATP eksikliği ile Na⁺/K⁺ ATPaz pompası bozulur.`,C:`Yanlış. Koagülatif, sıvılaşma (likefaksiyon), gangrenöz, kazeöz, yağ ve fibrinoid nekroz.`,D:`Yanlış. Bakteri, virüs, mantar ve parazitlerin tümü hasar verebilir.`,A:`Yanlış. Artmış eozinofili (denatüre proteinlere eozin bağlanması, RNA kaybı), camsı homojen görünüm ve vakuolizasyon.`,B:`Yanlış. Zararlı uyarı kaldırıldığında hücrenin normale dönebildiği durumdur.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q16`,kazanim:4,zorluk:`orta`,soru:`"Nekrozun sitoplazmik değişiklikleri" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Artmış eozinofili (denatüre proteinlere eozin bağlanması, RNA kaybı), camsı homojen görünüm ve vakuolizasyon.`,E:`Hücresel şişme, yağlanma, plazma zarında kabarcıklanma/mikrovillus kaybı, ER dilatasyonu, ribozom ayrılması, mitokondri şişmesi, kromatin yoğunlaşması, miyelin figürleri.`,D:`Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,A:`Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,B:`Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`},dogru:`C`,aciklama:`Doğru: Artmış eozinofili (denatüre proteinlere eozin bağlanması, RNA kaybı), camsı homojen görünüm ve vakuolizasyon.`,sik_aciklamalari:{C:`Doğru. Artmış eozinofili (denatüre proteinlere eozin bağlanması, RNA kaybı), camsı homojen görünüm ve vakuolizasyon.`,E:`Yanlış. Hücresel şişme, yağlanma, plazma zarında kabarcıklanma/mikrovillus kaybı, ER dilatasyonu, ribozom ayrılması, mitokondri şişmesi, kromatin yoğunlaşması, miyelin figürleri.`,D:`Yanlış. Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,A:`Yanlış. Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,B:`Yanlış. Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`},bilgi:[24],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k04-q17`,kazanim:4,zorluk:`zor`,soru:`"Yağlanma (steatoz)" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,E:`Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,C:`Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`,D:`İskemik arter tıkanmaları, akciğer hastalıkları, anemi, karbon monoksit zehirlenmesi, şiddetli kan kaybı/şok.`,A:`Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`},dogru:`B`,aciklama:`Doğru: Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,sik_aciklamalari:{B:`Doğru. Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,E:`Yanlış. Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,C:`Yanlış. Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`,D:`Yanlış. İskemik arter tıkanmaları, akciğer hastalıkları, anemi, karbon monoksit zehirlenmesi, şiddetli kan kaybı/şok.`,A:`Yanlış. Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`},bilgi:[19],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:5,metin:`Geri dönüşümlü hasarın geri dönüşümsüz hale geçiş kriterlerini sıralar.`,sorular:[{id:`k1-04-q15`,kazanim:5,zorluk:`kolay`,soru:`Aşağıdakilerden hangisi hücre hasarının geri dönüşümsüz hale geldiğini gösteren kriterlerden biridir?`,secenekler:{A:`Hücresel şişme`,B:`Mitokondriyal fonksiyonun geri kazanılamaması`,C:`Endoplazmik retikulum dilatasyonu`,D:`Hücre içinde yağ vakuolleri`,E:`Mikrovillus kaybı`},dogru:`B`,aciklama:`Geri dönüşümsüzlük kriterleri mitokondriyal fonksiyonun geri kazanılamaması, zarlarda kalıcı hasar ve DNA-kromatin bütünlüğünün bozulmasıdır.`,sik_aciklamalari:{A:`Geri dönüşümlü hasarın en erken bulgusudur.`,B:`Doğru. ATP üretimi kalıcı olarak bozulur.`,C:`Geri dönüşümlü hasarda görülür.`,D:`Yağlanma geri dönüşümlü hasardır.`,E:`Geri dönüşümlü hasarda görülür.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-04-q16`,kazanim:5,zorluk:`orta`,soru:`Geri dönüşümlü hasardan geri dönüşümsüz hasara geçiş ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?`,secenekler:{A:`Kalıcı veya şiddetli stres geri dönüşümlü hasar sınırını aşar.`,B:`Plazma ve organel zarlarında kalıcı hasar geri dönüşümsüzlük kriteridir.`,C:`DNA ve kromatin bütünlüğünün bozulması geri dönüşümsüzlük kriteridir.`,D:`Geri dönüşümsüz hasarın sonucu hücre ölümüdür.`,E:`Hücresel şişme ve yağlanma geri dönüşümsüzlüğün kesin kriterleridir.`},dogru:`E`,aciklama:`Şişme ve yağlanma geri dönüşümlü hasarın bulgularıdır; geri dönüşümsüzlüğü mitokondri, zar ve DNA hasarının kalıcılığı belirler.`,sik_aciklamalari:{A:`Doğru ifade; şiddet ve süre hasarın geri dönüp dönmeyeceğini belirler.`,B:`Doğru ifade; zar hasarı hücre içeriğinin sızmasına yol açar.`,C:`Doğru ifade; DNA-kromatin bütünlüğünün bozulması geri dönüşümsüzlük kriteridir.`,D:`Doğru ifade; nekroz veya apoptoz gelişir.`,E:`Yanlış ifade (aranan cevap). Şişme ve yağlanma geri dönüşümlü hasarın bulgularıdır; geri dönüşümsüzlüğü mitokondri, zar ve DNA hasarının kalıcılığı belirler.`},bilgi:[16,20],benzer_cikmis:[]},{id:`k1-04-q17`,kazanim:5,zorluk:`zor`,soru:`İskemik miyokardın elektron mikroskobik incelemesinde mitokondrilerin belirgin şiştiği ve içlerinde büyük, amorf, elektron yoğun birikintiler bulunduğu görülüyor.

Bu bulgu ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Hücre fizyolojik hipertrofi içindedir.`,B:`Erken, kolayca geri dönebilen hasarı gösterir.`,C:`Birikintiler trigliserid damlacıklarıdır.`,D:`Bulgu apoptozun kaspaz aktivasyonunu gösterir.`,E:`Kalsiyum ve protein çökeltileridir; geri dönüşümsüz hasarı ve yaklaşan hücre ölümünü gösterir.`},dogru:`E`,aciklama:`Geç hasarda mitokondriler belirgin şişer ve içlerinde çökelmiş kalsiyum-protein içeren elektron yoğun birikintiler oluşur; bu geri dönüşümsüzlüğün işaretidir.`,sik_aciklamalari:{A:`Hipertrofide organel sayısı artar, bu tür birikintiler görülmez.`,B:`Erken hasarda mitokondrilerde yalnızca hafif şişme olur.`,C:`Trigliserid birikimi yağlanmadır; mitokondri içinde değil sitoplazmik vakuollerdedir.`,D:`Kaspaz aktivasyonu elektron mikroskobunda bu şekilde görülmez.`,E:`Doğru. Mitokondride kalsiyum-protein çökeltileri geç hasarı ve yaklaşan ölümü gösterir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q04`,kazanim:5,zorluk:`orta`,soru:`Uzamış iskemi sonrası miyokard hücrelerinde mitokondriyal fonksiyonun geri kazanılamadığı, zarlarda yaygın süreksizliklerin oluştuğu ve kromatin bütünlüğünün bozulduğu saptanmıştır. Bu bulgular hücrenin hangi basamağa geçtiğini gösterir?`,secenekler:{A:`Hücresel şişme ve sitoplazmik vakuolizasyon`,B:`Endoplazmik retikulum dilatasyonu ve ribozom ayrılması`,C:`Mitokondriyal fonksiyonun geri kazanılamaması ve zarlarda kalıcı hasar`,D:`Mitokondrilerde hafif şişme`,E:`Kromatin yoğunlaşması`},dogru:`C`,aciklama:`Geri dönüşümsüzlüğün kriterleri mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar ve DNA-kromatin bütünlüğünün bozulmasıdır. Sonuç hücre ölümüdür.`,sik_aciklamalari:{A:`Bunlar geri dönüşümlü hasar bulgularıdır.`,B:`Bunlar geri dönüşümlü hasar bulgularıdır.`,C:`Doğru. Bu üç kriter geri dönüşümsüzlüğü tanımlar ve sonuç hücre ölümüdür.`,D:`Hafif şişme geri dönüşümlüdür.`,E:`Hafif kromatin yoğunlaşması geri dönüşümlü basamakta görülür.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q05`,kazanim:5,zorluk:`zor`,soru:`Elektron mikroskopta iskemik böbrek tübül hücrelerinin mitokondrilerinde belirgin şişme ve içlerinde elektron yoğun çökeltiler izlenmiş, plazma zarında süreksizlikler saptanmıştır. Patolog bu bulguların geri dönüşümsüzlüğe işaret ettiğini belirtmiştir. Bu yorumla ilgili ifadelerden hangisi doğrudur?`,secenekler:{A:`Mitokondride hafif şişme hücrenin kurtulduğunu gösterir`,B:`Mitokondride elektron yoğun kalsiyum birikintileri ölümün yaklaştığını gösterir`,C:`Zar süreksizlikleri geri dönüşümlü hasarın bulgusudur`,D:`DNA bütünlüğü bozulsa da hücre her zaman kurtulur`,E:`Geç mitokondriyal değişiklikler fonksiyonu etkilemez`},dogru:`B`,aciklama:`Geç hasarda mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır; bu ölümün yaklaştığını gösterir. Zar süreksizlikleri ve DNA bütünlük kaybı diğer geç bulgulardır.`,sik_aciklamalari:{A:`Hafif şişme erken ve geri dönüşümlüdür; elektron yoğun birikintiler geç bulgudur.`,B:`Doğru. Çökelmiş kalsiyum ve protein içeren birikintiler geri dönüşümsüzlüğün ultrastrüktürel işaretidir.`,C:`Kalıcı zar hasarı geri dönüşümsüzlük kriteridir.`,D:`DNA bütünlük kaybı geri dönüşümsüzlük kriteridir.`,E:`Mitokondriyal fonksiyon kaybı ölümün anahtarıdır.`},bilgi:[21,20],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q06`,kazanim:5,zorluk:`orta`,soru:`Geri dönüşümsüz hasarın üç kriteri nedir?`,secenekler:{A:`Hücresel şişme ve yağlanma`,B:`ER dilatasyonu ve bleb`,C:`Mitokondri yetmezliği, kalıcı zar, DNA hasarı`,D:`Mikrovillus kaybı`,E:`Glikojen azalması`},dogru:`C`,aciklama:`Mitokondriyal iç zar hasarı ATP üretimini kalıcı olarak durdurursa hücre enerji açığını kapatamaz. Plazma ve organel zarlarındaki süreksizlikler iyon dengesini ve bölmelenmeyi ortadan kaldırır. Nükleer kromatinin parçalanması genetik programın kaybı anlamına gelir; bu üçlü tablo hücrenin artık kurtarılamayacağını gösterir.`,sik_aciklamalari:{A:`Bunlar geri dönüşümlü hasar bulgularıdır.`,B:`Bleb ve ER dilatasyonu geri dönüşümlüdür.`,C:`Doğru. Enerji, bütünlük ve genetik program kaybı geri dönüşümsüzlüğü tanımlar.`,D:`Mikrovillus kaybı geri dönüşümlü zedelenmedir.`,E:`Glikojen azalması erken ve geri dönüşümlü değişimdir.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q07`,kazanim:5,zorluk:`orta`,soru:`Geç (geri dönüşümsüz) hasarda mitokondride görülen özgül bulgu nedir?`,secenekler:{A:`Hafif mitokondri şişmesi`,B:`Kalsiyumlu elektron yoğun birikintiler`,C:`Ribozom ayrılması`,D:`Kromatin yoğunlaşması`,E:`Miyelin figürleri`},dogru:`B`,aciklama:`Geç hasarda mitokondriler belirgin şişer ve matrikslerinde çökelmiş kalsiyum ile denatüre protein içeren elektron yoğun amorf birikintiler görülür. Bu birikintiler, kalsiyum homeostazının çöktüğünü ve oksidatif fosforilasyonun durduğunu gösterir. Elektron mikroskobunda bu görünüm, hücre ölümünün yaklaştığının habercisidir.`,sik_aciklamalari:{A:`Hafif şişme geri dönüşümlü hasarda görülür.`,B:`Doğru. Amorf kalsiyum-protein çökeltileri geç hasarın ayırt edici bulgusudur.`,C:`Ribozom ayrılması geri dönüşümlü ER değişimidir.`,D:`Kromatin yoğunlaşması erken değişimdir.`,E:`Miyelin figürleri genel hasar bulgusudur, geç hasara özgü değildir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q08`,kazanim:5,zorluk:`orta`,soru:`Bir hücre zedelenmesinde geri dönüşümsüzlük sınırını (point of no return) belirleyen ve hücreyi kaçınılmaz nekroza götüren iki temel olay aşağıdakilerden hangisidir?`,secenekler:{A:`Ribozomların ayrılması ve laktik asit birikimi`,B:`Hücre zarının (plazma membranı) bütünlüğünün ağır ve kalıcı hasarı ile mitokondri disfonksiyonunun düzeltilemez hale gelmesi`,C:`Hücrenin hacminin büyümesi ve turgor artışı`,D:`Glikojen depolarının tükenmesi ve sitoplazmanın şişmesi`,E:`ER sisternalarının hafif genişlemesi`},dogru:`B`,aciklama:`Robbins patoloji ilkelerine göre geri dönüşümsüz hasarın anahtar kriterleri: 1. Plazma membran bütünlüğünün kaybı, 2. Mitokondri fonksiyonunun kalıcı kaybı ve ATP sentezinin imkansızlaşmasıdır.`,sik_aciklamalari:{"A, C, D, E":`Geri dönüşümlü evrenin düzelebilir değişiklikleridir.`,B:`Doğru. Membran bütünlüğü kaybı ve mitokondri çöküşü geri dönüşümsüzlüğün iki kesin kriteridir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q09`,kazanim:5,zorluk:`zor`,soru:`Geç dönem hücre hasarında mitokondri matriksinde elektron mikroskobuyla gözlenen ve geri dönüşümsüz hasarın en önemli ultrastrüktürel belirteçlerinden biri kabul edilen oluşum hangisidir?`,secenekler:{A:`Büyük amorf flokülan dansiteler (kalsiyum ve denatüre protein çökeltileri)`,B:`Artmış krista sayısı`,C:`Mitokondri içinde glikojen sentezi`,D:`Mitokondrinin bölünerek çoğalması`,E:`Mitokondri zarının kalınlaşması`},dogru:`A`,aciklama:`Geri dönüşümsüz aşamaya geçen hücrede mitokondri içine masif kalsiyum girişi olur ve matrikste kalsiyum-protein çökeltileri içeren 'büyük amorf dansiteler' (amorphous flocculent densities) oluşur.`,sik_aciklamalari:{A:`Doğru. Amorf dansiteler geri dönüşümsüz hasarın mitokondriyal kanıtıdır.`,"B, C, D, E":`Hücresel ölümde görülmeyen durumlardır.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q10`,kazanim:5,zorluk:`orta`,soru:`Plazma zarı geçirgenliğinin bozulması ve membran parçalanması sonucu hücre içi enzimlerin kana sızması klinik pratikte nasıl kullanılır?`,secenekler:{A:`Kandaki enzim düzeyleri ölçülerek hasarın varlığı ve hangi dokunun nekroza gittiği tespit edilir (örn. kardiyak troponin ve CK-MB ile miyokard infarktüsü tanısı).`,B:`Enzimlerin kanda yükselmesi hastanın tamamen iyileştiğini gösterir.`,C:`Enzimler kanda pıhtılaşmayı engellediği için tedavi amaçlı kullanılır.`,D:`Hiçbir tanısal değeri yoktur.`,E:`Sadece kan basıncını ölçmek için kullanılır.`},dogru:`A`,aciklama:`Nekrozda hücre zarı parçalanır; dokuya özgü intraselüler enzimler (kalpte Troponin ve CK-MB, karaciğerde ALT ve AST) kana sızar. Serumda bu enzimlerin tespiti nekrozun yerini ve boyutunu gösterir.`,sik_aciklamalari:{A:`Doğru. Plazma membran hasarı sonucu kana sızan enzimler klinik nekroz tanısının temelidir.`,"B, C, D, E":`Tıbbi ve klinik gerçeklerle bağdaşmaz.`},bilgi:[12,14],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q11`,kazanim:5,zorluk:`zor`,soru:`Geri dönüşümsüz hücre hasarında sitozol içine kontrolsüz masif kalsiyum (Ca2+) girişinin aktive ettiği ve hücrenin kendi kendini yıkmasına yol açan enzimler arasında hangisi yer almaz?`,secenekler:{A:`Fosfolipazlar (hücre ve organel zarlarını parçalar)`,B:`Proteazlar (yapısal ve sitoiskelet proteinlerini yıkar)`,C:`Endonükleazlar (DNA ve kromatini parçalar)`,D:`ATPazlar (kalan son ATP moleküllerini tüketir)`,E:`DNA polimeraz ve RNA polimeraz (DNA replikasyonunu ve gen onarımını 10 kat hızlandırır)`},dogru:`E`,aciklama:`Sitozolik Ca2+ artışı; Fosfolipaz, Proteaz, Endonükleaz ve ATPaz enzimlerini aktive ederek hücreyi hızla nekroza sürükler. Polimerazlar ise nükleotid sentez enzimidir; nekrozda aktive olup sentez yapmazlar.`,sik_aciklamalari:{"A, B, C, D":`Kalsiyumun aktive ettiği hücre yıkıcı 4 ölümcül enzim grubudur.`,E:`Doğru (yer almaz). Polimerazlar hücre ölümünde aktive olup tamir yapamaz.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q12`,kazanim:5,zorluk:`orta`,soru:`Lizozom zarının parçalanması ve asit hidrolaz enzimlerinin sitoplazmaya boşalması sürecinin hücredeki nihai sonucu nedir?`,secenekler:{A:`Hücre bileşenlerinin enzimatik olarak erimesi ve otolitik nekroz`,B:`Hücrenin mitozla ikiye bölünmesi`,C:`Hücrenin kollajen sentezini artırması`,D:`Hücrenin glukoz depolaması`,E:`Doku pH'sının aşırı bazikleşmesi`},dogru:`A`,aciklama:`Lizozom zarlarının parçalanması RNaz, DNaz ve katepsin gibi enzimlerin sitozole salınmasına ve hücrenin kendi kendini sindirmesine (otoliz/nekroz) neden olur.`,sik_aciklamalari:{A:`Doğru. Asit hidrolazların sızması otolitik enzimatik nekrozla sonuçlanır.`,"B, C, D, E":`Hücresel otoliz tablosuyla ilgisiz durumlardır.`},bilgi:[12,14],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q13`,kazanim:5,zorluk:`kolay`,soru:`Aşağıdakilerden "Nekrozun temel özellikleri" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{C:`Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,E:`Farklı hücre tipleri aynı strese farklı yanıt verir; iskelet kası 2-3 saat, kalp kası 20-30 dakika iskemiyi tolere eder.`,A:`Çevresel (hava kirleticileri, böcek ilaçları, karbon monoksit, asbest), yaşam tarzı (sigara, etanol) ve ilaç kaynaklı.`,B:`Nekroz kazara hücre ölümüdür, enerji yetersizliği/toksik hasara bağlıdır ve her zaman patolojiktir; apoptoz programlıdır ve fizyolojik-patolojik olabilir.`,D:`Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`},dogru:`C`,aciklama:`Doğru: Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,sik_aciklamalari:{C:`Doğru. Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`,E:`Yanlış. Farklı hücre tipleri aynı strese farklı yanıt verir; iskelet kası 2-3 saat, kalp kası 20-30 dakika iskemiyi tolere eder.`,A:`Yanlış. Çevresel (hava kirleticileri, böcek ilaçları, karbon monoksit, asbest), yaşam tarzı (sigara, etanol) ve ilaç kaynaklı.`,B:`Yanlış. Nekroz kazara hücre ölümüdür, enerji yetersizliği/toksik hasara bağlıdır ve her zaman patolojiktir; apoptoz programlıdır ve fizyolojik-patolojik olabilir.`,D:`Yanlış. Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q14`,kazanim:5,zorluk:`orta`,soru:`"Püy ve apse" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Püy (irin) sarı-krem renkli nekrotik materyaldir.`,B:`Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`,D:`Yetersiz alım (protein-kalori malnütrisyonu, vitamin eksiklikleri) ve aşırı alım (obezite, tip 2 diyabet, ateroskleroz).`,E:`Normalde konak savunmasında gereklidir.`,A:`Artmış eozinofili (denatüre proteinlere eozin bağlanması, RNA kaybı), camsı homojen görünüm ve vakuolizasyon.`},dogru:`C`,aciklama:`Doğru: Püy (irin) sarı-krem renkli nekrotik materyaldir.`,sik_aciklamalari:{C:`Doğru. Püy (irin) sarı-krem renkli nekrotik materyaldir.`,B:`Yanlış. Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`,D:`Yanlış. Yetersiz alım (protein-kalori malnütrisyonu, vitamin eksiklikleri) ve aşırı alım (obezite, tip 2 diyabet, ateroskleroz).`,E:`Yanlış. Normalde konak savunmasında gereklidir.`,A:`Yanlış. Artmış eozinofili (denatüre proteinlere eozin bağlanması, RNA kaybı), camsı homojen görünüm ve vakuolizasyon.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q15`,kazanim:5,zorluk:`orta`,soru:`"Hücresel şişmenin makroskobik görünümü" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{E:`Birçok hücre etkilendiğinde organ soluk görünür, turgoru artar, ağırlığı artabilir.`,D:`Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`,C:`Sağlıklı hücre → zararlı uyaran → geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü (nekroz/apoptoz).`,B:`Doku tamamen erir ve viskoz sıvıya döner.`,A:`En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`},dogru:`E`,aciklama:`Doğru: Birçok hücre etkilendiğinde organ soluk görünür, turgoru artar, ağırlığı artabilir.`,sik_aciklamalari:{E:`Doğru. Birçok hücre etkilendiğinde organ soluk görünür, turgoru artar, ağırlığı artabilir.`,D:`Yanlış. Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`,C:`Yanlış. Sağlıklı hücre → zararlı uyaran → geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü (nekroz/apoptoz).`,B:`Yanlış. Doku tamamen erir ve viskoz sıvıya döner.`,A:`Yanlış. En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k05-q16`,kazanim:5,zorluk:`zor`,soru:`"Geri dönüşümsüzlük kriterleri" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{C:`Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,B:`İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`,D:`Sonuç etkenin türüne, süresine ve şiddetine bağlıdır.`,E:`Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,A:`Zararlı uyarı kaldırıldığında hücrenin normale dönebildiği durumdur.`},dogru:`C`,aciklama:`Doğru: Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,sik_aciklamalari:{C:`Doğru. Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,B:`Yanlış. İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`,D:`Yanlış. Sonuç etkenin türüne, süresine ve şiddetine bağlıdır.`,E:`Yanlış. Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,A:`Yanlış. Zararlı uyarı kaldırıldığında hücrenin normale dönebildiği durumdur.`},bilgi:[20],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:6,metin:`Nekroz ve apoptozun temel ayrımını yapar.`,sorular:[{id:`k1-04-q18`,kazanim:6,zorluk:`kolay`,soru:`Nekroz ile ilgili aşağıdaki ifadelerden hangisi doğrudur?`,secenekler:{A:`Programlı ve enerji gerektiren fizyolojik bir hücre ölümüdür.`,B:`Embriyonik gelişimde parmak arası dokunun ortadan kalkmasını sağlar.`,C:`Şiddetli enerji yetersizliği veya toksik hasara bağlı 'kazara' hücre ölümüdür ve her zaman patolojiktir.`,D:`Çevre dokuda inflamasyon oluşturmaz.`,E:`Hücre zarı daima sağlam kalır.`},dogru:`C`,aciklama:`Nekroz kazara, her zaman patolojik ölümdür; zarlar parçalanır ve inflamasyon gelişir. Apoptoz ise programlıdır ve fizyolojik olabilir.`,sik_aciklamalari:{A:`Bu tanım apoptoza aittir.`,B:`Bu fizyolojik apoptoz örneğidir.`,C:`Doğru. Nekroz enerji yetersizliği veya toksik hasara bağlı, her zaman patolojik ölümdür.`,D:`Nekrozda içerik sızar ve inflamatuar yanıt oluşur.`,E:`Nekrozda hücre ve organel zarları parçalanır.`},bilgi:[22,23],benzer_cikmis:[]},{id:`k1-04-q19`,kazanim:6,zorluk:`orta`,soru:`Nekroz ve apoptozun karşılaştırılmasında aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Nekroz her zaman patolojiktir; apoptoz fizyolojik veya patolojik olabilir.`,B:`Nekrozda zarlar parçalanır ve içerik dışarı sızar.`,C:`Nekroz çevre dokuda inflamasyona yol açar.`,D:`Apoptoz programlı ve düzenlenmiş hücre ölümüdür.`,E:`Apoptoz yalnızca patolojik durumlarda görülür.`},dogru:`E`,aciklama:`Apoptoz programlı hücre ölümüdür ve hem fizyolojik hem patolojik koşullarda görülür.`,sik_aciklamalari:{A:`Doğru ifade; nekroz patolojik, apoptoz fizyolojik veya patolojik olabilir.`,B:`Doğru ifade; zar hasarı içeriğin sızmasına yol açar.`,C:`Doğru ifade; sızan içerik inflamasyonu tetikler.`,D:`Doğru ifade; apoptoz kendi ölüm programını aktive eden düzenlenmiş ölümdür.`,E:`Yanlış ifade (aranan cevap). Apoptoz programlı hücre ölümüdür ve hem fizyolojik hem patolojik koşullarda görülür.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-04-q20`,kazanim:6,zorluk:`zor`,soru:`Aşağıdakilerden hangisi nekroz ve apoptoz dışında tanımlanmış düzenlenmiş hücre ölümü tiplerinden biri değildir?`,secenekler:{A:`Nekroptoz`,B:`Piroptoz`,C:`Ferroptoz`,D:`Hidropik değişim`,E:`Hiçbiri; hepsi hücre ölümü tipidir`},dogru:`D`,aciklama:`Nekroptoz, piroptoz ve ferroptoz diğer hücre ölümü tipleridir; hidropik değişim geri dönüşümlü hasarın bulgusudur.`,sik_aciklamalari:{A:`Nekroptoz tanımlanmış bir hücre ölümü tipidir.`,B:`Piroptoz tanımlanmış bir hücre ölümü tipidir.`,C:`Ferroptoz tanımlanmış bir hücre ölümü tipidir.`,D:`Doğru cevap. Hidropik değişim (hücresel şişme) ölüm değil, geri dönüşümlü hasardır.`,E:`Hidropik değişim hücre ölümü tipi olmadığı için bu seçenek yanlıştır.`},bilgi:[22,17],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q04`,kazanim:6,zorluk:`orta`,soru:`Miyokard enfarktüsünde ölen hücrelerin çevresinde yoğun nötrofil infiltrasyonu izlenirken, embriyogenezde parmak aralarındaki hücrelerin sessizce kaybolduğu ve inflamasyon oluşmadığı gözlenmiştir. Bu iki ölüm biçiminin temel ayrımı aşağıdakilerden hangisidir?`,secenekler:{A:`Nekroz programlı, apoptoz kazara ölümdür`,B:`Nekroz her zaman fizyolojiktir`,C:`Apoptozda hücre zarı parçalanır ve inflamasyon oluşur`,D:`Nekroz enerji bağımlı düzenli bir süreçtir`,E:`Nekroz kontrolsüz ve inflamasyonlu, apoptoz programlı ve sessiz ölümdür`},dogru:`E`,aciklama:`Nekroz kazara, enerji yetersizliği ve toksik hasara bağlı kontrolsüz ölümdür ve her zaman patolojiktir; apoptoz programlı, enerji bağımlı ölümdür ve fizyolojik de olabilir. Nekrozda zar parçalanır ve inflamasyon oluşur, apoptozda zar korunur ve inflamasyon minimaldir.`,sik_aciklamalari:{A:`Tanımlar terstir; nekroz kazara, apoptoz programlıdır.`,B:`Nekroz her zaman patolojiktir.`,C:`Zar parçalanması ve inflamasyon nekrozun özelliğidir.`,D:`Enerji bağımlı düzenli süreç apoptozdur.`,E:`Doğru. Nekrozda içerik sızar ve inflamasyon oluşur; apoptozda hücre sessizce temizlenir.`},bilgi:[22,23],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q05`,kazanim:6,zorluk:`zor`,soru:`TNF sinyaliyle tetiklenen düzenli ancak nekroz benzeri ölüm ile inflamozom aktivasyonuyla ateş ve IL-1 salınımına yol açan ölüm bir seminerde tartışılmaktadır. Bu ölüm biçimleriyle ilgili ifadelerden hangisi doğrudur?`,secenekler:{A:`Nekroptoz, piroptoz ve ferroptoz klasik nekroz-apoptoz ayrımının dışında kalan ölüm biçimleridir`,B:`Nekroz ve apoptoz dışında hiçbir hücre ölümü biçimi tanımlanmamıştır`,C:`Piroptozda inflamasyon görülmez`,D:`Ferroptoz kalsiyum bağımlı bir süreçtir`,E:`Nekroptoz tamamen kontrolsüz bir süreçtir`},dogru:`A`,aciklama:`Nekroptoz düzenli ancak nekroz benzeri, piroptoz inflamozom aracılı ateş ve IL-1 ile seyreden, ferroptoz demir bağımlı lipid peroksidasyonuyla giden ölüm biçimleridir. Klasik ikili ayrımın dışında kalan bu tipler güncel araştırma konusudur.`,sik_aciklamalari:{A:`Doğru. Bunlar hibrit veya düzenli özellikler taşıyan, gelişmekte olan ölüm kavramlarıdır.`,B:`Nekroptoz, piroptoz ve ferroptoz tanımlanmıştır.`,C:`Piroptozda IL-1 salınımı, ateş ve inflamasyon belirgindir.`,D:`Ferroptoz demir bağımlı lipid peroksidasyonudur.`,E:`Nekroptoz düzenli bir ölüm biçimidir.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q06`,kazanim:6,zorluk:`orta`,soru:`Nekroz ile apoptoz arasındaki temel ayrım nedir?`,secenekler:{A:`Nekroz kazara ve patolojik, apoptoz programlı`,B:`İkisi de her zaman fizyolojiktir`,C:`Nekroz programlı, apoptoz kazara`,D:`İkisi de inflamasyon yapar`,E:`İkisi aynı mekanizmadır`},dogru:`A`,aciklama:`Nekroz, şiddetli enerji yetersizliği veya toksik hasar sonucu hücrenin kazara ölümüdür ve her zaman patolojiktir. Zarlar parçalanır, hücre içeriği dışarı sızar ve çevre dokuda inflamasyon başlar. Apoptoz ise kaspazlarla yürütülen programlı ölümdür; embriyogenez gibi fizyolojik süreçlerde de görülür ve inflamasyon oluşturmaz.`,sik_aciklamalari:{A:`Doğru. Enerji çöküşüyle kazara ölüm her zaman patolojiktir, programlı ölüm fizyolojik olabilir.`,B:`Nekroz asla fizyolojik değildir.`,C:`Tanımlar ters çevrilmiştir.`,D:`Apoptozda zar bütünlüğü korunduğu için inflamasyon olmaz.`,E:`Mekanizmalar ve sonuçlar farklıdır.`},bilgi:[22,23],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q07`,kazanim:6,zorluk:`orta`,soru:`Nekrozun doku düzeyindeki ayırt edici özelliği nedir?`,secenekler:{A:`Nekrozda zarlar korunur`,B:`Nekrozda inflamasyon olmaz`,C:`Apoptozda içerik sızar`,D:`Nekroz sessizce temizlenir`,E:`Zar parçalanması ve inflamasyon`},dogru:`E`,aciklama:`Nekrozda parçalanan zarlardan sızan hücre içi moleküller (DAMP'ler) çevre makrofaj ve nötrofilleri aktive eder. Lizozomal ve lökosit enzimleri ölü hücreleri sindirirken inflamatuar yanıt dokuda kızarıklık ve ödeme yol açar. Bu inflamasyon, nekrozu apoptozdan ayıran doku düzeyindeki en önemli farktır.`,sik_aciklamalari:{A:`Zar parçalanması nekrozun ayırt edici özelliğidir.`,B:`İçerik sızıntısı inflamasyonu tetikler.`,C:`Apoptozda apoptotik cisimler fagosite edilir, sızıntı olmaz.`,D:`Sessiz temizlenme apoptozun özelliğidir.`,E:`Doğru. Zar yıkımı ve DAMP aracılı inflamasyon nekrozu tanımlar.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q08`,kazanim:6,zorluk:`orta`,soru:`Nekroz ile Apoptozun hücre boyutu, membran bütünlüğü ve inflamasyon açısından karşılaştırılması hangisinde doğru verilmiştir?`,secenekler:{A:`Nekrozda hücre büzüşür; apoptozda hücre şişer ve patlar.`,B:`Nekrozda hücre şişer, plazma zarı parçalanır ve çevre dokuda belirgin inflamasyon oluşur; Apoptozda hücre büzüşür, membran intakt kalır, apoptotik cisimcikler oluşur ve inflamasyon görülmez.`,C:`Her iki ölüm şeklinde de daima masif nötrofil infiltrasyonu ve apse gelişir.`,D:`Apoptoz daima patolojiktir, nekroz daima fizyolojiktir.`,E:`Nekrozda hücreler fagosite edilirken apoptozda hiçbir zaman fagositoz olmaz.`},dogru:`B`,aciklama:`Nekroz: Hücre şişmesi, membran parçalanması, içerik sızıntısı ve sekonder inflamasyon. Apoptoz: Hücre büzüşmesi, intakt membran, apoptotik cisimcikler ve inflamasyonsuz hızlı makrofaj temizliği.`,sik_aciklamalari:{A:`Hücre boyutu değişiklikleri ters verilmiştir.`,B:`Doğru. Nekroz ve apoptozun temel patolojik ayrım tablosudur.`,C:`Apoptozda inflamasyon olmaz.`,D:`Nekroz daima patolojiktir; apoptoz çoğunlukla fizyolojiktir.`,E:`Apoptotik cisimcikler makrofajlarca hızla fagosite edilir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q09`,kazanim:6,zorluk:`zor`,soru:`Aşağıdaki hücre ölümü senaryolarından hangisi 'fizyolojik apoptoz'a örnektir?`,secenekler:{A:`Koroner arter tıkanıklığı sonrası sol ventrikül miyokardında gelişen hücre ölümü`,B:`Böbrek enfarktüsünde tübül hücrelerinin ölümü`,C:`Embriyogenez sırasında el ve ayak parmakları arasındaki perdelerin (interdijital dokunun) programlı olarak ortadan kalkması`,D:`Akut bakteriyel menenjitte beyin dokusunda irinleşme`,E:`Diyabetik ayakta gangren gelişmesi`},dogru:`C`,aciklama:`İnterdijital doku kaybı, embriyogenezde morfolojik lümen ve parmak oluşumunu sağlayan klasik fizyolojik apoptoz örneğidir. Miyokard infarktüsü, böbrek enfarktüsü, apse ve gangren ise patolojik nekroz örnekleridir.`,sik_aciklamalari:{"A, B, D, E":`Patolojik iskemik veya enfeksiyöz nekroz tablolarıdır.`,C:`Doğru. Parmak aralarındaki dokunun kaybı fizyolojik programlı apoptozdur.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q10`,kazanim:6,zorluk:`orta`,soru:`Apoptoz sürecinde hücrenin çevre dokuda inflamasyona yol açmadan sessizce ortadan kaldırılabilmesinin temel nedeni nedir?`,secenekler:{A:`Hücrenin sitotoksik gazlar salgılaması`,B:`Plazma zarının parçalanmaması, hücresel içeriklerin 'apoptotik cisimcikler' adı verilen zarla çevrili paketler halinde paketlenmesi ve yüzeylerindeki fosfatidilserin sinyalleri ile makrofajlar tarafından anında yutulması`,C:`Ölen hücrenin kana karışarak idrarla atılması`,D:`Apoptozun sadece kemik dokusunda görülmesi`,E:`Hücre zarına antikor yapışması`},dogru:`B`,aciklama:`Apoptotik cisimcikler plazma zarıyla çevrili kalır ve hücresel enzimler dışarı sızmaz. Dış yaprağa dönen fosfatidilserin 'beni ye' sinyali verir; makrofajlar inflamasyon başlatmadan hücreyi temizler.`,sik_aciklamalari:{"A, C, D, E":`Apoptoz mekanizmasıyla ilgisiz ifadelerdir.`,B:`Doğru. Zar bütünlüğünün korunması ve apoptotik cisimciklerin fagositozu inflamasyonu önler.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q11`,kazanim:6,zorluk:`zor`,soru:`DNA hasarı onarılamayan bir hücrede p53 tümör baskılayıcı geninin aktivasyonu sonucu hücrenin apoptoza yönlendirilmesi hangi kaspaz aktivasyon yolağı ile gerçekleşir?`,secenekler:{A:`Fas/FasL ölüm reseptörü ekstrinsik yolağı`,B:`Mitokondriyal (intrinsik) apoptotik yolak (Sitokrom c salınımı ve Kaspaz-9 aktivasyonu)`,C:`Kompleman C5b-9 yolağı`,D:`İnflamazom ve Kaspaz-1 yolağı`,E:`Koagülasyon faktör Xa yolağı`},dogru:`B`,aciklama:`DNA hasarında p53 birikir; Bax ve Bak gibi pro-apoptotik proteinleri aktive eder. Mitokondri zar geçirgenliği artar, Sitokrom c sitozole sızarak Apaf-1 ile apoptozom kurar ve Kaspaz-9'u (intrinsik yolak) tetikler.`,sik_aciklamalari:{A:`Ekstrinsik ölüm reseptörü yolağıdır (Kaspaz-8).`,B:`Doğru. DNA hasarına yanıt mitokondriyal intrinsik apoptoz yolağıdır.`,C:`Hücre lizis kompleksidir.`,D:`Piroptoz inflamatuar yolağıdır.`,E:`Pıhtılaşma kaskadıdır.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q12`,kazanim:6,zorluk:`orta`,soru:`Her zaman patolojik olan, asla fizyolojik bir süreç olarak görülmeyen ve geniş doku alanlarında hücre yıkımıyla seyreden ölüm biçimi hangisidir?`,secenekler:{A:`Nekroz`,B:`Apoptoz`,C:`Otofaji`,D:`Atrofi`,E:`Metaplazi`},dogru:`A`,aciklama:`Nekroz her zaman patolojik bir olaydır; hücrenin kontrolsüz zedelenmesi sonucu ortaya çıkar. Apoptoz ise hem fizyolojik hem patolojik olabilir.`,sik_aciklamalari:{A:`Doğru. Nekroz daima patolojik bir hücre ölümüdür.`,B:`Apoptoz fizyolojik durumlarda da çok yaygındır.`,"C, D, E":`Hücresel adaptasyon süreçleridir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q13`,kazanim:6,zorluk:`kolay`,soru:`Aşağıdakilerden "Hücre hasarı kavramı" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{C:`Hücrenin normal homeostazını koruyamadığı durumdur.`,A:`Bakteri, virüs, mantar ve parazitlerin tümü hasar verebilir.`,B:`Nekroz kazara hücre ölümüdür, enerji yetersizliği/toksik hasara bağlıdır ve her zaman patolojiktir; apoptoz programlıdır ve fizyolojik-patolojik olabilir.`,E:`Hücre içi ve lökosit enzimleri ölü hücreleri sindirir; miyelin figürleri zar fosfolipidlerinden türer.`,D:`İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`},dogru:`C`,aciklama:`Doğru: Hücrenin normal homeostazını koruyamadığı durumdur.`,sik_aciklamalari:{C:`Doğru. Hücrenin normal homeostazını koruyamadığı durumdur.`,A:`Yanlış. Bakteri, virüs, mantar ve parazitlerin tümü hasar verebilir.`,B:`Yanlış. Nekroz kazara hücre ölümüdür, enerji yetersizliği/toksik hasara bağlıdır ve her zaman patolojiktir; apoptoz programlıdır ve fizyolojik-patolojik olabilir.`,E:`Yanlış. Hücre içi ve lökosit enzimleri ölü hücreleri sindirir; miyelin figürleri zar fosfolipidlerinden türer.`,D:`Yanlış. İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q14`,kazanim:6,zorluk:`orta`,soru:`"Nekrozun nükleer değişiklikleri" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`,D:`Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`,C:`Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,E:`Hipoksi oksijen eksikliği, iskemi kan akımının azalması veya kesilmesidir.`,B:`Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`},dogru:`A`,aciklama:`Doğru: Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`,sik_aciklamalari:{A:`Doğru. Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`,D:`Yanlış. Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`,C:`Yanlış. Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,E:`Yanlış. Hipoksi oksijen eksikliği, iskemi kan akımının azalması veya kesilmesidir.`,B:`Yanlış. Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q15`,kazanim:6,zorluk:`orta`,soru:`"Sıvılaşma (likefaksiyon) nekrozu" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Doku tamamen erir ve viskoz sıvıya döner.`,D:`Nekroz kazara hücre ölümüdür, enerji yetersizliği/toksik hasara bağlıdır ve her zaman patolojiktir; apoptoz programlıdır ve fizyolojik-patolojik olabilir.`,B:`Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`,C:`Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,E:`Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`},dogru:`A`,aciklama:`Doğru: Doku tamamen erir ve viskoz sıvıya döner.`,sik_aciklamalari:{A:`Doğru. Doku tamamen erir ve viskoz sıvıya döner.`,D:`Yanlış. Nekroz kazara hücre ölümüdür, enerji yetersizliği/toksik hasara bağlıdır ve her zaman patolojiktir; apoptoz programlıdır ve fizyolojik-patolojik olabilir.`,B:`Yanlış. Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`,C:`Yanlış. Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,E:`Yanlış. Hücre-organel zarları parçalanır, içerik dışarı sızar ve çevre dokuda inflamatuar yanıt oluşur.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k06-q16`,kazanim:6,zorluk:`zor`,soru:`"Koagülatif nekroz" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{C:`En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,B:`Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,A:`Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`,E:`Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,D:`Hücrenin normal homeostazını koruyamadığı durumdur.`},dogru:`C`,aciklama:`Doğru: En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,sik_aciklamalari:{C:`Doğru. En sık görülen tiptir; doku mimarisi birkaç gün korunur, doku sert-soluk-kuru görünür.`,B:`Yanlış. Mitokondriyal fonksiyonun geri kazanılamaması, plazma-organel zarlarında kalıcı hasar, DNA-kromatin bütünlüğünün bozulması.`,A:`Yanlış. Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`,E:`Yanlış. Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,D:`Yanlış. Hücrenin normal homeostazını koruyamadığı durumdur.`},bilgi:[28],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:7,metin:`Nekrozun sitoplazmik ve nükleer değişikliklerini açıklar.`,sorular:[{id:`k1-04-q21`,kazanim:7,zorluk:`kolay`,soru:`Nekrotik hücrede çekirdeğin büzülerek küçülmesi ve bazofilisinin artmasına ne ad verilir?`,secenekler:{A:`Karyolizis`,B:`Karyoreksis`,C:`Piknoz`,D:`Kromatolizis`,E:`Vakuolizasyon`},dogru:`C`,aciklama:`Piknozda çekirdek büzülür ve bazofilisi artar; karyoreksiste parçalanır, karyoliziste bazofilisini kaybederek solar.`,sik_aciklamalari:{A:`Karyolizis bazofili kaybı ve çekirdeğin solmasıdır.`,B:`Karyoreksis piknotik çekirdeğin parçalanmasıdır.`,C:`Doğru. Piknozda çekirdek küçülür, koyulaşır ve bazofilisi artar.`,D:`Kromatolizis bu derste nekrozun nükleer değişikliği olarak tanımlanmaz.`,E:`Vakuolizasyon sitoplazmik bir değişikliktir.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-04-q22`,kazanim:7,zorluk:`orta`,soru:`Nekrotik hücrelerde HE boyamada sitoplazmanın daha pembe (eozinofilik) görünmesinin nedeni aşağıdakilerden hangisidir?`,secenekler:{A:`Denatüre proteinlere eozin bağlanması ve bazofilik RNA'nın kaybı`,B:`Glikojen birikiminin artması`,C:`Çekirdekte DNA miktarının artması`,D:`Ribozomların sayıca artması`,E:`Hücre içine kalsiyum girişinin azalması`},dogru:`A`,aciklama:`Nekrozda artmış eozinofili denatüre proteinlerin eozin bağlaması ve normalde bazofili sağlayan RNA'nın kaybıyla oluşur; glikojen kaybıyla camsı görünüm eklenir.`,sik_aciklamalari:{A:`Doğru. Denatüre proteinler eozin bağlar, RNA kaybı bazofiliyi azaltır; sitoplazma pembeleşir.`,B:`Nekrozda glikojen kaybolur; camsı görünüme katkı verir.`,C:`Çekirdekte DNA yıkılır (karyolizis); eozinofiliyle ilişkili değildir.`,D:`Ribozomal RNA kaybı bazofiliyi azaltır; ribozom artışı tersine bazofili yapar.`,E:`Hasarlı hücrede kalsiyum girişi artar; eozinofili nedeni değildir.`},bilgi:[24],benzer_cikmis:[]},{id:`k1-04-q23`,kazanim:7,zorluk:`zor`,soru:`Nekrozdaki değişiklikler ve nekrotik hücrelerin akıbeti ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?`,secenekler:{A:`Nükleer değişiklikler sırasıyla piknoz, karyoreksis ve karyolizis biçiminde görülebilir.`,B:`1-2 gün içinde çekirdek tamamen kaybolabilir.`,C:`Miyelin figürleri hücre zarı fosfolipidlerinden türer.`,D:`Yağ asitlerinin kalsiyumla birleşmesi distrofik kalsifikasyona yol açabilir.`,E:`Nekrotik hücreler yalnızca kendi lizozomal enzimleriyle sindirilir; lökositlerin katkısı yoktur.`},dogru:`E`,aciklama:`Ölü hücreler hem kendi lizozomal enzimleri hem de bölgeye gelen lökositlerin enzimleriyle sindirilir.`,sik_aciklamalari:{A:`Doğru ifade; nükleer değişiklikler piknoz, karyoreksis ve karyolizis biçimindedir.`,B:`Doğru ifade; çekirdek 1-2 günde tamamen kaybolabilir.`,C:`Doğru ifade; elektron mikroskobunda görülür.`,D:`Doğru ifade; yağ asidi-kalsiyum birleşimi distrofik kalsifikasyona yol açar.`,E:`Yanlış ifade (aranan cevap). Ölü hücreler hem kendi lizozomal enzimleri hem de bölgeye gelen lökositlerin enzimleriyle sindirilir.`},bilgi:[23,25,26],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q04`,kazanim:7,zorluk:`orta`,soru:`Enfarktüs alanından alınan kesitte hücrelerin sitoplazmasının yoğun pembe boyandığı, çekirdeklerin büzüşmüş, parçalanmış veya tamamen silinmiş olduğu izlenmiştir. Elektron mikroskopta zar süreksizlikleri ve miyelin figürleri görülmüştür. Bu bulgular aşağıdakilerden hangisini tanımlar?`,secenekler:{A:`Sitoplazmik bazofili artışı ve çekirdekte kromatin açılması`,B:`Artmış eozinofili ile piknoz, karyoreksis ve karyolizis`,C:`Hücre küçülmesi ve apoptotik cisim oluşumu`,D:`Çift zarlı otofagozom birikimi`,E:`Çekirdekte mitotik figür artışı`},dogru:`B`,aciklama:`Nekrozda sitoplazmada artmış eozinofili, camsı homojen görünüm ve vakuolizasyon; çekirdekte piknoz, karyoreksis ve karyolizis izlenir. Eozinofili denatüre proteinlere eozin bağlanması ve RNA kaybına bağlıdır.`,sik_aciklamalari:{A:`Bazofili artışı değil eozinofili artışı ve çekirdek büzüşmesi görülür.`,B:`Doğru. Sitoplazmik eozinofili ile nükleer büzüşme, parçalanma ve erime nekrozun klasik üçlüsüdür.`,C:`Bunlar apoptozun morfolojisidir.`,D:`Otofagozom birikimi otofajinin bulgusudur.`,E:`Mitotik figür proliferasyonu gösterir, nekrozu değil.`},bilgi:[24,25],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q05`,kazanim:7,zorluk:`zor`,soru:`İskemik böbrek dokusunda çekirdekleri büzüşmüş ve koyu boyanan hücrelerin yanında çekirdeği parçalanmış hücreler ve çekirdeği tamamen silinmiş hayalet hücreler bir arada izlenmiştir. Bu nükleer değişiklik dizisiyle ilgili ifadelerden hangisi doğrudur?`,secenekler:{A:`Piknoz çekirdeğin şişip solmasıdır`,B:`Karyolizis çekirdeğin parçalanmasıdır`,C:`Nekrotik hücreler hiçbir zaman temizlenemez`,D:`Karyoreksis piknotik çekirdeğin parçalanmasıdır ve çekirdek 1-2 günde kaybolabilir`,E:`Miyelin figürleri ribozomlardan türer`},dogru:`D`,aciklama:`Piknozda çekirdek büzüşür ve bazofili artar, karyoreksiste parçalanır, karyoliziste bazofili kaybolup çekirdek solar; 1-2 gün içinde çekirdek tamamen kaybolabilir. Nekrotik kalıntılar makrofajlarca temizlenir ve yağ asitleri kalsiyumla birleşerek distrofik kalsifikasyon yapabilir.`,sik_aciklamalari:{A:`Piknoz büzüşme ve bazofili artışıdır; solma karyolizistir.`,B:`Karyolizis bazofilinin kaybı ve solmadır.`,C:`Hücre içi ve lökosit enzimleri ölü hücreleri sindirir, makrofajlar temizler.`,D:`Doğru. Nükleer değişiklik sırası piknoz, karyoreksis ve karyolizistir.`,E:`Miyelin figürleri zar fosfolipidlerinden türer.`},bilgi:[25,26],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q06`,kazanim:7,zorluk:`orta`,soru:`Nekrozun sitoplazmik değişikliklerini doğru veren seçenek hangisidir?`,secenekler:{A:`Bazofili artar, sitoplazma granüler`,B:`Eozinofili artar, camsı homojen görünüm`,C:`Çekirdek büyür, kromatin açılır`,D:`Mitokondri çoğalır`,E:`Glikojen artar`},dogru:`B`,aciklama:`Nekrozda proteinler denatüre olur ve bazofilik RNA kaybolur, bu yüzden asidik eozin boyası denatüre sitoplazmik proteinlere yoğun bağlanır. Glikojen kaybı ve protein çökmesi sitoplazmaya camsı, homojen bir görünüm verir. Elektron mikroskobunda zar süreksizlikleri, mitokondri şişmesi ve lizozom rüptürü izlenir.`,sik_aciklamalari:{A:`RNA kaybı bazofiliyi azaltır, artırmaz.`,B:`Doğru. Protein denatürasyonu ve RNA kaybı eozin tutulumunu artırır.`,C:`Çekirdek büzülür ve kaybolur, büyümez.`,D:`Mitokondriler şişer ve işlevini yitirir, çoğalmaz.`,E:`Glikojen kaybı camsı görünümün nedenidir.`},bilgi:[24],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q07`,kazanim:7,zorluk:`orta`,soru:`Nekrozda nükleer değişikliklerin doğru sırası nedir?`,secenekler:{A:`Karyolizis, karyoreksis, piknoz`,B:`Mitoz, mayoz, apoptoz`,C:`Hipertrofi, hiperplazi, atrofi`,D:`Piknoz, karyoreksis, karyolizis`,E:`Metaplazi, displazi, neoplazi`},dogru:`D`,aciklama:`Önce çekirdek büzülür ve kromatin yoğunlaşmasıyla bazofili artar (piknoz). Ardından büzüşmüş çekirdek parçalanır (karyoreksis) ve son olarak nükleer boyanabilirlik kaybolarak çekirdek solar (karyolizis). Bir-iki gün içinde çekirdek tümüyle kaybolur.`,sik_aciklamalari:{A:`Sıra terstir, önce büzülme olur.`,B:`Bunlar hücre bölünme ve ölüm tipleridir.`,C:`Bunlar adaptasyon tipleridir.`,D:`Doğru. Büzülme, parçalanma ve solma sırası nükleer yıkımı tanımlar.`,E:`Bunlar proliferasyon spektrumudur.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q08`,kazanim:7,zorluk:`orta`,soru:`Nekroza uğrayan hücrelerin rutin H&E boyalı kesitlerinde sitoplazmalarının canlı hücrelere göre çok daha koyu pembe-kırmızı (artmış eozinofili) boyanmasının temel iki nedeni nedir?`,secenekler:{A:`Sitoplazmada su oranının artması ve glukoz birikmesi`,B:`İntraselüler bazofilik RNA moleküllerinin ribonükleazlarca parçalanarak kaybolması ve denatüre olan sitoplazmik proteinlerin eozin boyasına afinitesinin artması`,C:`Hücreye aşırı miktarda kalsiyum girmesi`,D:`Mitokondrilerin maviye boyanması`,E:`Hücre çekirdeğinin bölünmesi`},dogru:`B`,aciklama:`Nekrotik hücrelerde mavi boyanan sitoplazmik RNA (ribozomlar) yıkıldığı için bazofili kaybolur; proteinler denatüre olup katlandıkça eozini daha fazla bağlar; bu nedenle sitoplazma parlak pembe (hipeozinofilik) görünür.`,sik_aciklamalari:{"A, C, D, E":`Hipeozinofili mekanizmasını açıklamaz.`,B:`Doğru. RNA kaybı ve denatüre proteinlerin eozin bağlaması artmış eozinofilinin nedenidir.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q09`,kazanim:7,zorluk:`orta`,soru:`Nekroz sürecinde nükleusun kromatin yoğunlaşması göstererek büzüşmesi, küçülmesi ve koyu mavi-siyah yoğun bir kütleye dönüşmesi morfolojik olarak nasıl adlandırılır?`,secenekler:{A:`Piknoz (Pyknosis)`,B:`Karyoreksis (Karyorrhexis)`,C:`Karyolizis (Karyolysis)`,D:`Sitokinez`,E:`Karyotipleme`},dogru:`A`,aciklama:`Nükleer nekroz değişiklikleri üç evrelidir: 1. Piknoz: Çekirdek büzülür ve yoğunlaşır. 2. Karyoreksis: Piknotik çekirdek parçalanır. 3. Karyolizis: DNaz etkisiyle kromatin erir ve çekirdek hayaleti kalır.`,sik_aciklamalari:{A:`Doğru. Çekirdeğin büzüşüp küçülmesi piknozdur.`,B:`Karyoreksis parçalanmadır.`,C:`Karyolizis erime ve solmadır.`,"D ve E":`Farklı sitolojik kavramlardır.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q10`,kazanim:7,zorluk:`orta`,soru:`Piknoza uğramış nükleusun parçalanarak sitoplazma içine dağılmış küçük kromatin granüllerine ayrılması durumu hangi terimle ifade edilir?`,secenekler:{A:`Karyolizis`,B:`Karyoreksis (Karyorrhexis)`,C:`Piknoz`,D:`Apoptozom`,E:`Miyelin figürü`},dogru:`B`,aciklama:`Piknotik nükleusun nükleazlarca parçalara bölünmesine 'karyoreksis' denir.`,sik_aciklamalari:{A:`Karyolizis kromatoliz ve erimedir.`,B:`Doğru. Nükleusun parçalanması karyoreksistir.`,C:`Piknoz büzüşmedir.`,"D ve E":`Farklı yapılardır.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q11`,kazanim:7,zorluk:`orta`,soru:`Nekrotik hücrede endonükleaz enzimlerinin DNA'yı tamamen parçalaması sonucu nükleusun bazofilisini (mavi boyanmasını) kaybetmesi, soluklaşması ve 1-2 gün içinde çekirdeğin tamamen silinip kaybolması süreci hangisidir?`,secenekler:{A:`Karyolizis (Karyolysis)`,B:`Piknoz`,C:`Karyoreksis`,D:`Hiperkromatizm`,E:`Polisitemi`},dogru:`A`,aciklama:`Karyolizis (karyo: çekirdek + lysis: erime), DNaz aktivitesiyle nükleer DNA'nın sindirilmesi ve çekirdeğin tamamen solup kaybolmasıdır.`,sik_aciklamalari:{A:`Doğru. Çekirdeğin eriyip solması karyolizisdir.`,B:`Piknoz koyulaşmadır.`,C:`Karyoreksis fragmantasyondur.`,D:`Kanser hücrelerindeki aşırı koyu çekirdektir.`,E:`Eritrosit artışıdır.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q12`,kazanim:7,zorluk:`zor`,soru:`Nekrotik hücrelerin sitoplazmasında ve ekstraselüler alanda parçalanan fosfolipid hücre zarlarından köken alan, konsantrik kıvrımlı helezonik lameller şeklinde görülen yapılara ne ad verilir?`,secenekler:{A:`Russell cisimcikleri`,B:`Mallory-Denk cisimcikleri`,C:`Miyelin figürleri (Myelin figures)`,D:`Psammom cisimcikleri`,E:`Lewy cisimcikleri`},dogru:`C`,aciklama:`Miyelin figürleri, hasarlı organel ve plazma zarlarından açığa çıkan fosfolipidlerin sulu ortamda oluşturduğu konsantrik tabakalı membran helezonlarıdır; kalsiyum tuzlarını bağlayarak distrofik kalsifikasyona öncülük ederler.`,sik_aciklamalari:{A:`İmmünoglobulin depo cisimcikleridir.`,B:`Karaciğerde sitokeratin agregatlarıdır.`,C:`Doğru. Membran fosfolipidlerinden oluşan konsantrik lameller miyelin figürleridir.`,D:`Kalsifiye lamellerdir.`,E:`Parkinson nöronal inklüzyonudur.`},bilgi:[10,14],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q13`,kazanim:7,zorluk:`kolay`,soru:`"Hedef hücre ve genetik zemin" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Farklı hücre tipleri aynı strese farklı yanıt verir; iskelet kası 2-3 saat, kalp kası 20-30 dakika iskemiyi tolere eder.`,A:`Bakteri, virüs, mantar ve parazitlerin tümü hasar verebilir.`,D:`Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir.`,B:`Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,E:`Hücrenin normal homeostazını koruyamadığı durumdur.`},dogru:`C`,aciklama:`Doğru: Farklı hücre tipleri aynı strese farklı yanıt verir; iskelet kası 2-3 saat, kalp kası 20-30 dakika iskemiyi tolere eder.`,sik_aciklamalari:{C:`Doğru. Farklı hücre tipleri aynı strese farklı yanıt verir; iskelet kası 2-3 saat, kalp kası 20-30 dakika iskemiyi tolere eder.`,A:`Yanlış. Bakteri, virüs, mantar ve parazitlerin tümü hasar verebilir.`,D:`Yanlış. Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir.`,B:`Yanlış. Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,E:`Yanlış. Hücrenin normal homeostazını koruyamadığı durumdur.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q14`,kazanim:7,zorluk:`orta`,soru:`"Beyin infarktı istisnası" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{C:`İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`,B:`Normalde konak savunmasında gereklidir.`,A:`Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,D:`Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`,E:`Hücrenin normal homeostazını koruyamadığı durumdur.`},dogru:`C`,aciklama:`Doğru: İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`,sik_aciklamalari:{C:`Doğru. İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`,B:`Yanlış. Normalde konak savunmasında gereklidir.`,A:`Yanlış. Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,D:`Yanlış. Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`,E:`Yanlış. Hücrenin normal homeostazını koruyamadığı durumdur.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q15`,kazanim:7,zorluk:`orta`,soru:`"Koagülatif nekroz mikroskopisi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,C:`Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,D:`Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,B:`İskemik arter tıkanmaları, akciğer hastalıkları, anemi, karbon monoksit zehirlenmesi, şiddetli kan kaybı/şok.`,E:`Yetersiz alım (protein-kalori malnütrisyonu, vitamin eksiklikleri) ve aşırı alım (obezite, tip 2 diyabet, ateroskleroz).`},dogru:`A`,aciklama:`Doğru: Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,sik_aciklamalari:{A:`Doğru. Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,C:`Yanlış. Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,D:`Yanlış. Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,B:`Yanlış. İskemik arter tıkanmaları, akciğer hastalıkları, anemi, karbon monoksit zehirlenmesi, şiddetli kan kaybı/şok.`,E:`Yanlış. Yetersiz alım (protein-kalori malnütrisyonu, vitamin eksiklikleri) ve aşırı alım (obezite, tip 2 diyabet, ateroskleroz).`},bilgi:[29],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k07-q16`,kazanim:7,zorluk:`zor`,soru:`"Beyin infarktı istisnası" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{B:`İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`,D:`Püy (irin) sarı-krem renkli nekrotik materyaldir.`,E:`Normalde konak savunmasında gereklidir.`,C:`Hücresel şişme, yağlanma, plazma zarında kabarcıklanma/mikrovillus kaybı, ER dilatasyonu, ribozom ayrılması, mitokondri şişmesi, kromatin yoğunlaşması, miyelin figürleri.`,A:`Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir.`},dogru:`B`,aciklama:`Doğru: İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`,sik_aciklamalari:{B:`Doğru. İskemik enfarktlar tipik olarak koagülatif nekrozla seyreder.`,D:`Yanlış. Püy (irin) sarı-krem renkli nekrotik materyaldir.`,E:`Yanlış. Normalde konak savunmasında gereklidir.`,C:`Yanlış. Hücresel şişme, yağlanma, plazma zarında kabarcıklanma/mikrovillus kaybı, ER dilatasyonu, ribozom ayrılması, mitokondri şişmesi, kromatin yoğunlaşması, miyelin figürleri.`,A:`Yanlış. Hücre ölümü tipik olarak ultrastrüktürel, ışık mikroskobik ve makroskobik değişikliklerden önce gelir.`},bilgi:[33],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:8,metin:`Başlıca doku nekrozu kalıplarını (koagülatif, sıvılaşma, gangrenöz) örnekleriyle açıklar.`,sorular:[{id:`k1-04-q24`,kazanim:8,zorluk:`kolay`,soru:`En sık görülen nekroz tipi ve kalp, böbrek, dalak gibi organlardaki iskemik enfarktların tipik nekrozu aşağıdakilerden hangisidir?`,secenekler:{A:`Likefaksiyon nekrozu`,B:`Kazeöz nekroz`,C:`Yağ nekrozu`,D:`Koagülatif nekroz`,E:`Fibrinoid nekroz`},dogru:`D`,aciklama:`Koagülatif nekroz en sık tiptir; yapısal proteinler ve enzimler denatüre olduğu için doku mimarisi birkaç gün korunur.`,sik_aciklamalari:{A:`Likefaksiyon nekrozu püy oluşturan enfeksiyonlar ve beyin infarktlarında görülür.`,B:`Kazeöz nekroz tüberkülozla ilişkilidir.`,C:`Yağ nekrozu pankreatit ve meme travmasıyla ilişkilidir.`,D:`Doğru. Koagülatif nekroz en sık tiptir ve solid organ enfarktlarının tipik nekrozudur.`,E:`Fibrinoid nekroz damar duvarında immün kompleks birikimiyle ilişkilidir.`},bilgi:[28],benzer_cikmis:[`28b4d100f48e`]},{id:`k1-04-q25`,kazanim:8,zorluk:`orta`,soru:`İskemik inme geçiren bir hastanın beyninde enfarkt alanında görülmesi beklenen nekroz tipi aşağıdakilerden hangisidir?`,secenekler:{A:`Likefaksiyon (sıvılaşma) nekrozu`,B:`Koagülatif nekroz`,C:`Kazeöz nekroz`,D:`Fibrinoid nekroz`,E:`Gangrenöz nekroz`},dogru:`A`,aciklama:`İskemik enfarktlar genellikle koagülatif nekrozla seyreder; beyin infarktları bu kuralın istisnasıdır ve sıvılaşma nekrozu gösterir.`,sik_aciklamalari:{A:`Doğru. Beyinde iskemi likefaksiyon nekrozu oluşturur.`,B:`Koagülatif nekroz beyin dışındaki solid organ enfarktlarında görülür.`,C:`Kazeöz nekroz tüberküloza özgüdür.`,D:`Fibrinoid nekroz damar duvarında görülür.`,E:`Gangren klinik bir terimdir; genellikle ekstremitelerde kullanılır.`},bilgi:[30,33],benzer_cikmis:[`d3-b-113`,`4c8b0d8dbd53`]},{id:`k1-04-q26`,kazanim:8,zorluk:`orta`,soru:`Koagülatif nekrozun morfolojik özellikleri ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Doku hızla sıvılaşarak viskoz bir kitleye dönüşür.`,B:`Mikroskopide çekirdekler kaybolur fakat hücre konturları korunur; doku sert, soluk ve kuru görünür.`,C:`Tipik olarak beyin infarktlarında görülür.`,D:`Peynirimsi, beyaz-sarı ufalanan bir görünüm vardır.`,E:`Proteoliz hızlandığı için doku mimarisi ilk saatlerde kaybolur.`},dogru:`B`,aciklama:`Koagülatif nekrozda proteinler ve enzimler denatüre olduğu için proteoliz gecikir; doku mimarisi ve hücre konturları birkaç gün korunur.`,sik_aciklamalari:{A:`Bu sıvılaşma nekrozunun özelliğidir.`,B:`Doğru. Proteoliz geciktiği için hücre konturları ve doku mimarisi birkaç gün korunur.`,C:`Beyin infarktları sıvılaşma nekrozu gösterir.`,D:`Peynirimsi görünüm kazeöz nekroza aittir.`,E:`Proteoliz gecikir; mimari birkaç gün korunur.`},bilgi:[28,29],benzer_cikmis:[]},{id:`k1-04-q28`,kazanim:8,zorluk:`orta`,soru:`Deri altında gelişen bakteriyel bir enfeksiyonda lokalize, sarı-krem renkli, nekrotik materyal içeren boşluk oluşumu ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Lökosit ve mikrobiyal enzimlerin dokuyu sıvılaştırmasıyla oluşan likefaksiyon nekrozudur; bu lokalize püy birikimi apsedir.`,B:`Doku mimarisinin korunduğu koagülatif nekrozdur.`,C:`Tüberküloza özgü kazeöz nekrozdur.`,D:`Damar duvarında immün kompleks birikimiyle oluşan fibrinoid nekrozdur.`,E:`Geri dönüşümlü hasar olan hidropik değişimdir.`},dogru:`A`,aciklama:`Püy oluşturan bakteri ve mantar enfeksiyonları likefaksiyon nekrozu yapar; püyün lokalize birikimine apse denir.`,sik_aciklamalari:{A:`Doğru. Püy oluşturan enfeksiyonlarda doku sıvılaşır; lokalize püy birikimi apsedir.`,B:`Koagülatif nekrozda doku sıvılaşmaz.`,C:`Kazeöz nekroz peynirimsi görünümlüdür ve tüberkülozla ilişkilidir.`,D:`Fibrinoid nekroz vaskülitlerde damar duvarında görülür.`,E:`Hidropik değişim geri dönüşümlüdür ve püy oluşturmaz.`},bilgi:[30,31],benzer_cikmis:[`4c8b0d8dbd53`]},{id:`k1-04-q27`,kazanim:8,zorluk:`zor`,soru:`Periferik arter hastalığı olan diyabetik bir hastanın ayak parmağında kan akımı kesilmesine bağlı siyah, kuru bir alan gelişiyor; günler sonra bölgeye bakteriyel enfeksiyon eklenerek doku yumuşayıp kötü kokulu hale geliyor.

Bu tablo ile ilgili aşağıdaki ifadelerden hangisi doğrudur?`,secenekler:{A:`Gangrenöz nekroz klasik bir histolojik nekroz tipidir ve kazeöz nekrozla aynıdır.`,B:`Başlangıçtaki kuru gangren sıvılaşma nekrozu, sonraki ıslak gangren koagülatif nekrozdur.`,C:`Gangren klinik bir terimdir; temelde geniş koagülatif nekroz alanıdır ve enfeksiyon eklenince ikincil sıvılaşmayla ıslak gangren gelişir.`,D:`Bu tablo yağ nekrozuna örnektir.`,E:`Enfeksiyon eklenmesi nekrozun tipini değiştirmez.`},dogru:`C`,aciklama:`Gangrenöz nekroz genellikle alt ekstremitede kan akımı kesilen alanlarda görülen geniş koagülatif nekrozdur; enfeksiyonla sıvılaşma eklenir (ıslak gangren).`,sik_aciklamalari:{A:`Gangren histolojik değil klinik bir terimdir ve kazeöz nekrozla ilgisi yoktur.`,B:`Tipler ters verilmiştir: temel koagülatif, enfeksiyonla eklenen sıvılaşmadır.`,C:`Doğru. Gangren geniş koagülatif nekrozdur; enfeksiyon eklendiğinde ıslak gangrene döner.`,D:`Yağ nekrozu pankreas, meme gibi yağdan zengin dokularda görülür.`,E:`Enfeksiyon lökosit ve mikrobiyal enzimlerle ikincil sıvılaşma yapar.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q06`,kazanim:8,zorluk:`orta`,soru:`Ani göğüs ağrısı sonrası ölen hastanın kalbinde soluk, sert ve kuru görünümlü bir alan saptanmış, mikroskopta çekirdekler kaybolmuş ancak hücre konturları günlerce korunmuş olarak izlenmiştir. Bu tabloya uyan nekroz kalıbı ve örneği aşağıdakilerden hangisidir?`,secenekler:{A:`Beyin enfarktı`,B:`Bakteriyel apse`,C:`Miyokard enfarktı`,D:`Akut pankreatit`,E:`Poliarteritis nodozada damar duvarı`},dogru:`C`,aciklama:`Koagülatif nekroz en sık tiptir; protein denatürasyonu ve gecikmiş proteoliz nedeniyle doku mimarisi günlerce korunur, doku sert-soluk-kuru görünür. Kalp, böbrek ve dalak enfarktları tipik örneklerdir.`,sik_aciklamalari:{A:`Beyin enfarktlarında sıvılaşma nekrozu görülür.`,B:`Püy yapan enfeksiyonlar sıvılaşma nekrozu yapar.`,C:`Doğru. Kalp enfarktları koagülatif nekrozun tipik örneğidir; mimari korunur, çekirdek kaybı vardır.`,D:`Pankreatit yağ nekrozu yapar.`,E:`Damar duvarında fibrinoid nekroz görülür.`},bilgi:[28,29],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q07`,kazanim:8,zorluk:`zor`,soru:`İnme sonrası ölen hastanın beyninde kistik, sıvı dolu bir kavite saptanırken, ayağında dolaşım bozukluğu olan başka bir hastada kuru, siyahlaşmış gangrenöz doku izlenmiştir. Bu iki tabloyla ilgili ifadelerden hangisi doğrudur?`,secenekler:{A:`Beyin enfarktında sıvılaşma nekrozu görülmesi`,B:`Gangrenöz nekrozun özel bir histolojik tip olması`,C:`Kuru gangrende dokunun sıvılaşmış olması`,D:`Absenin organize solid doku birikimi olması`,E:`İskemik beyin dokusunun sert ve kuru kalması`},dogru:`A`,aciklama:`Sıvılaşma nekrozunda doku tamamen eriyip viskoz sıvıya döner; püy yapan enfeksiyonlar ve beyin enfarktları tipik nedenlerdir. Gangrenöz nekroz klinik bir terimdir ve geniş koagülatif nekrozu tanımlar; enfeksiyon eklenirse ıslak gangren gelişir.`,sik_aciklamalari:{A:`Doğru. Beyin iskemik enfarktların istisnasıdır; lökosit ve mikrobiyal enzimler dokuyu sıvılaştırır.`,B:`Gangrenöz nekroz histolojik tip değil klinik terimdir.`,C:`Kuru gangren koagülatif nekroz zeminindedir; sıvılaşma ıslak gangrendedir.`,D:`Apse lokalize püy birikimidir, sıvı niteliktedir.`,E:`Beyin sıvılaşır; sert-kuru görünüm koagülatif nekrozundur.`},bilgi:[30,31,32,33],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q08`,kazanim:8,zorluk:`orta`,soru:`Koagülatif nekrozun özelliği ve tipik örnekleri nedir?`,secenekler:{A:`Mimari korunur, kalp-böbrek-dalak enfarktı`,B:`Doku erir, beyin enfarktı`,C:`Püy birikir, apse oluşur`,D:`Yağ dokusu sabunlaşır`,E:`Damar duvarı fibrinoidleşir`},dogru:`A`,aciklama:`Koagülatif nekrozda yapısal proteinler ve enzimler denatüre olur, bu yüzden proteolitik sindirim gecikir ve doku mimarisi birkaç gün korunur. Doku sert, soluk ve kuru görünür; kalp, böbrek ve dalak enfarktları tipik örneklerdir. Mikroskopide çekirdeği kaybolmuş ancak konturları korunmuş hücreler ve inflamatuar infiltrasyon görülür.`,sik_aciklamalari:{A:`Doğru. Protein denatürasyonu proteolizi geciktirir, konturlar korunur.`,B:`Bu sıvılaşma nekrozunun özelliğidir.`,C:`Püy ve apse piyojenik enfeksiyonların sıvılaşma sonucudur.`,D:`Sabunlaşma yağ nekrozunun özelliğidir.`,E:`Fibrinoid nekroz damar duvarında görülür.`},bilgi:[28,29],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q09`,kazanim:8,zorluk:`orta`,soru:`Sıvılaşma (likefaksiyon) nekrozunun iki tipik örneği nedir?`,secenekler:{A:`Kalp enfarktüsü ve kuru gangren`,B:`Böbrek enfarktı ve dalak enfarktı`,C:`Beyin infarktı ve piyojenik apse`,D:`Kazeöz granülom ve yağ nekrozu`,E:`Fibrinoid damar ve kazeoz nodül`},dogru:`C`,aciklama:`Beyin dokusu lipidten zengin ve proteolitik enzim içeriği yüksek olduğundan iskemide hızla eriyerek viskoz sıvıya dönüşür. Piyojenik bakteri ve mantar enfeksiyonlarında ise lökosit ile mikrobiyal enzimler dokuyu sıvılaştırır ve sarı-krem püy birikir. Lokalize püy birikimine apse denir.`,sik_aciklamalari:{A:`Bunlar koagülatif nekroz örnekleridir.`,B:`Böbrek ve dalak enfarktları koagülatiftir.`,C:`Doğru. Beynin enzimatik yapısı ve püy yapan enfeksiyonlar sıvılaşmaya yol açar.`,D:`Kazeöz ve yağ nekrozu ayrı kalıplardır.`,E:`Fibrinoid nekroz damar patolojisidir.`},bilgi:[30,31,33],benzer_cikmis:[`5adcad6819be`]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q10`,kazanim:8,zorluk:`orta`,soru:`Tüm solid organlarda (beyin hariç) iskemik infarktüs sonucu en sık karşılaşılan, yapısal proteinlerin ve litik enzimlerin eşzamanlı denatüre olması nedeniyle doku mimarisinin birkaç gün boyunca 'hayalet hücre konturları' şeklinde korunduğu nekroz tipi hangisidir?`,secenekler:{A:`Koagülatif (pıhtılaşma) nekrozu`,B:`Likefaksiyon (sıvılaşma) nekrozu`,C:`Kazeöz nekroz`,D:`Fibrinoid nekroz`,E:`Yağ nekrozu`},dogru:`A`,aciklama:`Koagülatif nekroz, iskeminin prototipik sonucudur (miyokard, böbrek, dalak). Asidoz litik enzimleri de denatüre ettiğinden proteoliz gecikir; dokunun temel mimarisi günlerce korunur (hayalet hücreler).`,sik_aciklamalari:{A:`Doğru. Doku mimarisinin korunduğu iskemik nekroz koagülatif nekrozdur.`,B:`Likefaksiyonda mimari anında erir ve sıvılaşır.`,C:`Tüberküloza özgü peynirleşme nekrozudur.`,"D ve E":`Damar ve yağ dokusuna özgü tiplerdir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q11`,kazanim:8,zorluk:`zor`,soru:`İskemi sonucu gelişen doku nekrozu kalıpları değerlendirildiğinde 'Beyin dokusu enfarktüsü' (inme) neden diğer solid organlar gibi koagülatif nekroz yerine 'Sıvılaşma (Likefaksiyon) nekrozu' gösterir?`,secenekler:{A:`Beyin dokusunda hiçbir zaman kan damarı bulunmaması`,B:`Beyin dokusunun yüksek oranda lipid ve hidrolitik enzim içermesi, nöronal membranların zayıf bağ dokusu desteği nedeniyle hızla otolitik lizise uğraması ve mikroglial hücrelerin bölgeyi hızla sıvı kisti haline getirmesi`,C:`Beyinde kalsiyum bulunmaması`,D:`Beyin hücrelerinin sadece apoptoz yapabilmesi`,E:`Beyinde kaspaz enzimlerinin bulunmaması`},dogru:`B`,aciklama:`Santral sinir sistemi enfarktları istisnadır; zengin lipid içeriği ve litik enzimler nedeniyle koagülasyon oluşamaz, doku hızla sıvılaşır (ensefalomalazi) ve geride kistik bir kavite bırakır.`,sik_aciklamalari:{"A, C, D, E":`Beyin anatomisi ve patolojisiyle bağdaşmayan yanlış durumlardır.`,B:`Doğru. Zengin lipid ve litik enzim içeriği beyin enfarktüsünü sıvılaşma nekrozuna götürür.`},bilgi:[15,16],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q12`,kazanim:8,zorluk:`orta`,soru:`Fokal bakteriyel veya fungal enfeksiyonlarda (örneğin stafilokok apsesi) nötrofillerin bölgeye yoğun göçü ve nötrofil granüllerinden salınan güçlü hidrolitik enzimlerin dokuyu tamamen eriterek sarı-yeşil viskoz bir sıvıya (irin / püy) dönüştürdüğü nekroz tipi hangisidir?`,secenekler:{A:`Koagülatif nekroz`,B:`Sıvılaşma (Likefaksiyon) nekrozu`,C:`Kazeöz nekroz`,D:`Enzimatik yağ nekrozu`,E:`Kuru gangren`},dogru:`B`,aciklama:`Piyojenik bakteri enfeksiyonları güçlü nötrofilik yanıt oluşturur. Nötrofil enzimleri parankimi tamamen eritip sıvılaştırır; oluşan bu sıvı nekrotik birikime irin (püy), lezyona apse ve nekroz tipine likefaksiyon nekrozu denir.`,sik_aciklamalari:{A:`Koagülatif nekroz katı kalır.`,B:`Doğru. İrinleşme ve doku erimesi sıvılaşma (likefaksiyon) nekrozudur.`,C:`Kazeöz granülomatöz tüberkülozdur.`,D:`Pankreatitte görülür.`,E:`Enfeksiyonsuz iskemik koagülasyondur.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q13`,kazanim:8,zorluk:`zor`,soru:`Gangrenöz nekroz (gangrene) ile ilgili patolojik ve klinik tanımlamalardan hangisi doğrudur?`,secenekler:{A:`Spesifik tek bir hücresel nekroz kalıbı olup sadece dilde görülür.`,B:`Klasik histolojik bir terimden ziyade klinik bir tanımdır; genellikle alt ekstremitede kan akımının kesilmesiyle başlayan çok katlı koagülatif nekroz tablosuna 'kuru gangren'; bu tablonun üzerine bakteriyel enfeksiyon eklendiğinde litik enzimlerin etkisiyle sıvılaşma nekrozunun geliştiği tabloya ise 'yaş (ıslak) gangren' denir.`,C:`Kuru gangrende doku tamamen sıvılaşmıştır.`,D:`Yaş gangren sadece virüslerle oluşur.`,E:`Gangren hiçbir zaman cerrahi amputasyon gerektirmez.`},dogru:`B`,aciklama:`Gangren cerrahi ve klinik bir terimdir. İskemik bacakta enfeksiyonsuz siyah-kuru koagülatif nekroz 'kuru gangren'dir; üzerine bakteri süperenfeksiyonu eklenip likefaksiyon başladığında 'yaş gangren' tablosu gelişir.`,sik_aciklamalari:{A:`Spesifik histolojik tip değildir, cerrahi klinik terimdir.`,B:`Doğru. Kuru gangren (koagülatif) + süperenfeksiyon ve likefaksiyon = yaş gangren.`,C:`Kuru gangren sıvılaşmamıştır, mumyalaşmış katıdır.`,D:`Bakteriyel enfeksiyonlarla oluşur.`,E:`İlerleyen gangren majör amputasyon gerektirir.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q14`,kazanim:8,zorluk:`orta`,soru:`Böbrek biyopsisinde veya otopsisinde kama şeklinde (tabanı kortekse, tepesi hilusa bakan), belirgin sınırlı, soluk sarı renkli ve mikroskopisinde nükleusları kaybolmuş ancak glomerül ve tübül taslak konturları halen seçilebilen bir enfarktüs lezyonunda saptanan temel nekroz kalıbı hangisidir?`,secenekler:{A:`Koagülatif nekroz`,B:`Likefaksiyon nekrozu`,C:`Kazeöz granülom`,D:`Fibrinoid arterit`,E:`Mukoid dejenerasyon`},dogru:`A`,aciklama:`Böbrek enfarktüsleri kama şeklinde klasik koagülatif nekrozdur; nükleus kaybolur ancak doku mimarisi ve tübül gölgeleri korunur.`,sik_aciklamalari:{A:`Doğru. Kama şeklinde solid organ enfarktüsü koagülatif nekrozun prototipidir.`,"B, C, D, E":`Farklı morfolojiye sahip nekroz veya dejenerasyon türleridir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q15`,kazanim:8,zorluk:`kolay`,soru:`"Fiziksel etkenler" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{B:`Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,D:`İskemik arter tıkanmaları, akciğer hastalıkları, anemi, karbon monoksit zehirlenmesi, şiddetli kan kaybı/şok.`,E:`Sağlıklı hücre → zararlı uyaran → geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü (nekroz/apoptoz).`,A:`En erken geri dönüşümlü hasar bulgusudur; ATP eksikliği ile Na⁺/K⁺ ATPaz pompası bozulur.`,C:`Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`},dogru:`B`,aciklama:`Doğru: Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,sik_aciklamalari:{B:`Doğru. Mekanik travma, aşırı ısı/soğuk, iyonizan ve UV radyasyon, elektrik çarpması, ani basınç değişiklikleri.`,D:`Yanlış. İskemik arter tıkanmaları, akciğer hastalıkları, anemi, karbon monoksit zehirlenmesi, şiddetli kan kaybı/şok.`,E:`Yanlış. Sağlıklı hücre → zararlı uyaran → geri dönüşümlü hasar → geri dönüşümsüz hasar → hücre ölümü (nekroz/apoptoz).`,A:`Yanlış. En erken geri dönüşümlü hasar bulgusudur; ATP eksikliği ile Na⁺/K⁺ ATPaz pompası bozulur.`,C:`Yanlış. Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q16`,kazanim:8,zorluk:`orta`,soru:`"Hücresel hasarda ana hedefler" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`,D:`İskemik arter tıkanmaları, akciğer hastalıkları, anemi, karbon monoksit zehirlenmesi, şiddetli kan kaybı/şok.`,B:`Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,C:`Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`,E:`Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`},dogru:`A`,aciklama:`Doğru: Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`,sik_aciklamalari:{A:`Doğru. Plazma ve organel zarları, mitokondriler, protein sentez mekanizması, DNA-kromatin ve sitoplazmik iskelet.`,D:`Yanlış. İskemik arter tıkanmaları, akciğer hastalıkları, anemi, karbon monoksit zehirlenmesi, şiddetli kan kaybı/şok.`,B:`Yanlış. Trigliseridlerin sitoplazmik vakuollerde birikimidir; en sık karaciğer ve kalp kasında görülür.`,C:`Yanlış. Mitokondriler belirgin şişmiş olup içlerinde çökelmiş kalsiyum ve protein içeren elektron yoğun birikintiler vardır.`,E:`Yanlış. Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q17`,kazanim:8,zorluk:`orta`,soru:`"Hipoksi ve iskemi" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Hipoksi oksijen eksikliği, iskemi kan akımının azalması veya kesilmesidir.`,E:`Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`,B:`Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,C:`İskemik arter tıkanmaları, akciğer hastalıkları, anemi, karbon monoksit zehirlenmesi, şiddetli kan kaybı/şok.`,D:`Hücresel şişme, yağlanma, plazma zarında kabarcıklanma/mikrovillus kaybı, ER dilatasyonu, ribozom ayrılması, mitokondri şişmesi, kromatin yoğunlaşması, miyelin figürleri.`},dogru:`A`,aciklama:`Doğru: Hipoksi oksijen eksikliği, iskemi kan akımının azalması veya kesilmesidir.`,sik_aciklamalari:{A:`Doğru. Hipoksi oksijen eksikliği, iskemi kan akımının azalması veya kesilmesidir.`,E:`Yanlış. Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`,B:`Yanlış. Klasik histolojik bir tip değil, klinik bir terimdir; genellikle alt ekstremitede kan akımının kesildiği alanlarda görülür.`,C:`Yanlış. İskemik arter tıkanmaları, akciğer hastalıkları, anemi, karbon monoksit zehirlenmesi, şiddetli kan kaybı/şok.`,D:`Yanlış. Hücresel şişme, yağlanma, plazma zarında kabarcıklanma/mikrovillus kaybı, ER dilatasyonu, ribozom ayrılması, mitokondri şişmesi, kromatin yoğunlaşması, miyelin figürleri.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-04-hucre-hasari-ve-nekroz-i-k08-q18`,kazanim:8,zorluk:`zor`,soru:`"Genetik anormallikler" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{C:`Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`,D:`Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`,A:`Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,B:`Normalde konak savunmasında gereklidir.`,E:`Doku tamamen erir ve viskoz sıvıya döner.`},dogru:`C`,aciklama:`Doğru: Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`,sik_aciklamalari:{C:`Doğru. Kromozom bozuklukları (Down sendromu) ve nokta mutasyonları (orak hücreli anemi).`,D:`Yanlış. Piknoz (çekirdek büzülür, bazofili artar), karyoreksis (piknotik çekirdek parçalanır), karyolizis (bazofili kaybı, solma).`,A:`Yanlış. Nekrotik hücrelerde çekirdek kaybı ile birlikte korunmuş hücre konturları ve inflamatuar infiltrasyon izlenir.`,B:`Yanlış. Normalde konak savunmasında gereklidir.`,E:`Yanlış. Doku tamamen erir ve viskoz sıvıya döner.`},bilgi:[8],benzer_cikmis:[]}],ilgili_cikmis:[{id:`28b4d100f48e`,soru:`En sık görülen nekroz tipi hangisidir?`,secenekler:{A:`Kazeiikasyon nekrozu.`,B:`Fibrinoid nekroz.`,C:`Yağ nekrozu.`,D:`Koagülasyon nekrozu.`,E:`Likefaksiyon nekrozu.`},cevap:`B`},{id:`d3-b-113`,soru:`Beyinde iskemi sonucu hangi tipte nekroz oluşur?`,secenekler:{A:`Koagülasyon nekrozu`,B:`Likefaksiyon nekrozu`,C:`Kazeifikasyon nekrozu`,D:`Fibrinoid nekroz`,E:`Gangrenöz nekroz`},cevap:`B`},{id:`4c8b0d8dbd53`,soru:`Abseler ve beyin infarktüsü hangi nekroz tipine örnektir?`,secenekler:{A:`Kazeifikasyon`,B:`Fibrinoid nekroz`,C:`Yağ nekrozu`,D:`Koagülasyon nekrozu`,E:`Likefaksiyon nekrozu`},cevap:`B`}]}]};export{e as default};